// Generated from ecma262/spec.html — do not edit by hand.
const sections = {"1":"<p><dfn variants=\"Environment Records\">Environment Record</dfn> is a specification type used to define the association of <emu-nt><a href=\"/ecmascript-language-expressions#prod-Identifier\">Identifier</a></emu-nt>s to specific variables and functions, based upon the lexical nesting structure of ECMAScript code. Usually an Environment Record is associated with some specific syntactic structure of ECMAScript code such as a <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-FunctionDeclaration\">FunctionDeclaration</a></emu-nt>, a <emu-nt><a href=\"/ecmascript-language-statements-and-declarations#prod-BlockStatement\">BlockStatement</a></emu-nt>, or a <emu-nt><a href=\"/ecmascript-language-statements-and-declarations#prod-Catch\">Catch</a></emu-nt> clause of a <emu-nt><a href=\"/ecmascript-language-statements-and-declarations#prod-TryStatement\">TryStatement</a></emu-nt>. Each time such code is evaluated, a new Environment Record is created to record the identifier bindings that are created by that code.</p>\n    <p>Every Environment Record has an <var class=\"field\">[[OuterEnv]]</var> field, which is either <emu-val>null</emu-val> or a reference to an outer Environment Record. This is used to model the logical nesting of Environment Record values. The outer reference of an (inner) Environment Record is a reference to the Environment Record that logically surrounds the inner Environment Record. An outer Environment Record may, of course, have its own outer Environment Record. An Environment Record may serve as the outer environment for multiple inner Environment Records. For example, if a <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-FunctionDeclaration\">FunctionDeclaration</a></emu-nt> contains two nested <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-FunctionDeclaration\">FunctionDeclaration</a></emu-nt>s then the Environment Records of each of the nested functions will have as their outer Environment Record the Environment Record of the current evaluation of the surrounding function.</p>\n    <p>Environment Records are purely specification mechanisms and need not correspond to any specific artefact of an ECMAScript implementation. It is impossible for an ECMAScript program to directly access or manipulate such values.</p>\n\n    ","2":"<p>A <dfn id=\"privateenvironment-record\" variants=\"PrivateEnvironment Records\">PrivateEnvironment Record</dfn> is a specification mechanism used to track <emu-xref href=\"/ecmascript-data-types-and-values#sec-private-names\"><a href=\"/ecmascript-data-types-and-values#sec-private-names\">Private Names</a></emu-xref> based upon the lexical nesting structure of <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-ClassDeclaration\">ClassDeclaration</a></emu-nt>s and <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-ClassExpression\">ClassExpression</a></emu-nt>s in ECMAScript code. They are similar to, but distinct from, <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Records</a></emu-xref>. Each <emu-xref href=\"/executable-code-and-execution-contexts#privateenvironment-record\"><a href=\"/executable-code-and-execution-contexts#privateenvironment-record\">PrivateEnvironment Record</a></emu-xref> is associated with a <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-ClassDeclaration\">ClassDeclaration</a></emu-nt> or <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-ClassExpression\">ClassExpression</a></emu-nt>. Each time such a class is evaluated, a new <emu-xref href=\"/executable-code-and-execution-contexts#privateenvironment-record\"><a href=\"/executable-code-and-execution-contexts#privateenvironment-record\">PrivateEnvironment Record</a></emu-xref> is created to record the <emu-xref href=\"/ecmascript-data-types-and-values#sec-private-names\"><a href=\"/ecmascript-data-types-and-values#sec-private-names\">Private Names</a></emu-xref> declared by that class.</p>\n    <p>Each <emu-xref href=\"/executable-code-and-execution-contexts#privateenvironment-record\"><a href=\"/executable-code-and-execution-contexts#privateenvironment-record\">PrivateEnvironment Record</a></emu-xref> has the fields defined in <emu-xref href=\"#table-privateenvironment-records\"><a href=\"/executable-code-and-execution-contexts#table-privateenvironment-records\">Table 18</a></emu-xref>.</p>\n    <emu-table id=\"table-privateenvironment-records\" caption=\"PrivateEnvironment Record Fields\" data-num=\"18\">\n      <table>\n        <thead>\n          <tr>\n            <th>\n              Field Name\n            </th>\n            <th>\n              Value Type\n            </th>\n            <th>\n              Meaning\n            </th>\n          </tr>\n        </thead>\n        <tr>\n          <td>\n            <var class=\"field\">[[OuterPrivateEnvironment]]</var>\n          </td>\n          <td>\n            a <emu-xref href=\"/executable-code-and-execution-contexts#privateenvironment-record\"><a href=\"/executable-code-and-execution-contexts#privateenvironment-record\">PrivateEnvironment Record</a></emu-xref> or <emu-val>null</emu-val>\n          </td>\n          <td>\n            The <emu-xref href=\"/executable-code-and-execution-contexts#privateenvironment-record\"><a href=\"/executable-code-and-execution-contexts#privateenvironment-record\">PrivateEnvironment Record</a></emu-xref> of the nearest containing class. <emu-val>null</emu-val> if the class with which this <emu-xref href=\"/executable-code-and-execution-contexts#privateenvironment-record\"><a href=\"/executable-code-and-execution-contexts#privateenvironment-record\">PrivateEnvironment Record</a></emu-xref> is associated is not contained in any other class.\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <var class=\"field\">[[Names]]</var>\n          </td>\n          <td>\n            a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-private-names\"><a href=\"/ecmascript-data-types-and-values#sec-private-names\">Private Names</a></emu-xref>\n          </td>\n          <td>\n            The <emu-xref href=\"/ecmascript-data-types-and-values#sec-private-names\"><a href=\"/ecmascript-data-types-and-values#sec-private-names\">Private Names</a></emu-xref> declared by this class.\n          </td>\n        </tr>\n      </table>\n    </emu-table>\n\n    ","3":"<p>Before it is evaluated, all ECMAScript code must be associated with a <dfn id=\"realm\" variants=\"realms\">realm</dfn>. Conceptually, a <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref> consists of a set of intrinsic objects, an ECMAScript global environment, all of the ECMAScript code that is loaded within the scope of that global environment, and other associated state and resources.</p>\n    <p>A <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref> is represented in this specification as a <dfn id=\"realm-record\" variants=\"Realm Records\">Realm Record</dfn> with the fields specified in <emu-xref href=\"#table-realm-record-fields\"><a href=\"/executable-code-and-execution-contexts#table-realm-record-fields\">Table 19</a></emu-xref>:</p>\n    <emu-table id=\"table-realm-record-fields\" caption=\"Realm Record Fields\" oldids=\"table-21\" data-num=\"19\">\n      <table>\n        <thead>\n          <tr>\n            <th>\n              Field Name\n            </th>\n            <th>\n              Value\n            </th>\n            <th>\n              Meaning\n            </th>\n          </tr>\n        </thead>\n        <tr>\n          <td>\n            <var class=\"field\">[[AgentSignifier]]</var>\n          </td>\n          <td>\n            an <emu-xref href=\"/executable-code-and-execution-contexts#sec-agents\"><a href=\"/executable-code-and-execution-contexts#sec-agents\">agent signifier</a></emu-xref>\n          </td>\n          <td>\n            The <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> that owns this <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <var class=\"field\">[[Intrinsics]]</var>\n          </td>\n          <td>\n            a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref> whose field names are intrinsic keys and whose values are objects\n          </td>\n          <td>\n            The intrinsic values used by code associated with this <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <var class=\"field\">[[GlobalObject]]</var>\n          </td>\n          <td>\n            an Object\n          </td>\n          <td>\n            The <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref> for this <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <var class=\"field\">[[GlobalEnv]]</var>\n          </td>\n          <td>\n            a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref>\n          </td>\n          <td>\n            The global environment for this <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <var class=\"field\">[[TemplateMap]]</var>\n          </td>\n          <td>\n            a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Records</a></emu-xref> with fields <var class=\"field\">[[Site]]</var> (a <emu-nt><a href=\"/ecmascript-language-expressions#prod-TemplateLiteral\">TemplateLiteral</a></emu-nt> <emu-xref href=\"/notational-conventions#sec-syntactic-grammar\"><a href=\"/notational-conventions#sec-syntactic-grammar\">Parse Node</a></emu-xref>) and <var class=\"field\">[[Array]]</var> (an Array)\n          </td>\n          <td>\n            <p>Template objects are canonicalized separately for each <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref> using its <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref>'s <var class=\"field\">[[TemplateMap]]</var>. Each <var class=\"field\">[[Site]]</var> value is a <emu-xref href=\"/notational-conventions#sec-syntactic-grammar\"><a href=\"/notational-conventions#sec-syntactic-grammar\">Parse Node</a></emu-xref> that is a <emu-nt><a href=\"/ecmascript-language-expressions#prod-TemplateLiteral\">TemplateLiteral</a></emu-nt>. The associated <var class=\"field\">[[Array]]</var> value is the corresponding template object that is passed to a tag function.</p>\n            <emu-note data-num=\"1\"><span class=\"note\">Note 1</span><div class=\"note-contents\">Once a <emu-xref href=\"/notational-conventions#sec-syntactic-grammar\"><a href=\"/notational-conventions#sec-syntactic-grammar\">Parse Node</a></emu-xref> becomes unreachable, the corresponding <var class=\"field\">[[Array]]</var> is also unreachable, and it would be unobservable if an implementation removed the pair from the <var class=\"field\">[[TemplateMap]]</var> list.</div></emu-note>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <var class=\"field\">[[LoadedModules]]</var>\n          </td>\n          <td>\n            a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-language-scripts-and-modules#loadedmodulerequest-record\"><a href=\"/ecmascript-language-scripts-and-modules#loadedmodulerequest-record\">LoadedModuleRequest Records</a></emu-xref>\n          </td>\n          <td>\n            <p>A map from the specifier strings imported by this <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref> to the resolved <emu-xref href=\"/ecmascript-language-scripts-and-modules#sec-abstract-module-records\"><a href=\"/ecmascript-language-scripts-and-modules#sec-abstract-module-records\">Module Record</a></emu-xref>. The list does not contain two different <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Records</a></emu-xref> <var>r1</var> and <var>r2</var> such that <emu-xref aoid=\"ModuleRequestsEqual\"><a href=\"/ecmascript-language-scripts-and-modules#sec-ModuleRequestsEqual\">ModuleRequestsEqual</a></emu-xref>(<var>r1</var>, <var>r2</var>) is <emu-val>true</emu-val>.</p>\n            <emu-note data-num=\"2\"><span class=\"note\">Note 2</span><div class=\"note-contents\">\n              As mentioned in <emu-xref aoid=\"HostLoadImportedModule\"><a href=\"/ecmascript-language-scripts-and-modules#sec-HostLoadImportedModule\">HostLoadImportedModule</a></emu-xref> (<emu-xref href=\"#note-HostLoadImportedModule-referrer-Realm-Record\"><a href=\"/ecmascript-language-scripts-and-modules#note-HostLoadImportedModule-referrer-Realm-Record\">Note 1</a></emu-xref>), <var class=\"field\">[[LoadedModules]]</var> in <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Records</a></emu-xref> is only used when running an <code>import()</code> expression in a context where there is no <emu-xref href=\"/executable-code-and-execution-contexts#job-activescriptormodule\"><a href=\"/executable-code-and-execution-contexts#job-activescriptormodule\">active script or module</a></emu-xref>.\n            </div></emu-note>\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <var class=\"field\">[[HostDefined]]</var>\n          </td>\n          <td>\n            anything (default value is <emu-val>undefined</emu-val>)\n          </td>\n          <td>\n            Field reserved for use by <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">hosts</a></emu-xref> that need to associate additional information with a <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref>.\n          </td>\n        </tr>\n      </table>\n    </emu-table>\n\n    ","4":"<p>An <dfn variants=\"execution contexts\">execution context</dfn> is a specification device that is used to track the runtime evaluation of code by an ECMAScript implementation. At any point in time, there is at most one execution context per <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> that is actually executing code. This is known as the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>'s <dfn id=\"running-execution-context\" variants=\"running execution contexts\">running execution context</dfn>. All references to the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> in this specification denote the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> of the <emu-xref href=\"/executable-code-and-execution-contexts#surrounding-agent\"><a href=\"/executable-code-and-execution-contexts#surrounding-agent\">surrounding agent</a></emu-xref>.</p>\n    <p>The <dfn id=\"execution-context-stack\" variants=\"execution context stacks\">execution context stack</dfn> is used to track execution contexts. The <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> is always the top element of this stack. A new execution context is created whenever control is transferred from the executable code associated with the currently <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> to executable code that is not associated with that execution context. The newly created execution context is pushed onto the stack and becomes the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>.</p>\n    <p>An execution context contains whatever implementation specific state is necessary to track the execution progress of its associated code. Each execution context has at least the state components listed in <emu-xref href=\"#table-state-components-for-all-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#table-state-components-for-all-execution-contexts\">Table 20</a></emu-xref>.</p>\n    <emu-table id=\"table-state-components-for-all-execution-contexts\" caption=\"State Components for All Execution Contexts\" oldids=\"table-22\" data-num=\"20\">\n      <table>\n        <thead>\n          <tr>\n            <th>\n              Component\n            </th>\n            <th>\n              Purpose\n            </th>\n          </tr>\n        </thead>\n        <tr>\n          <td>\n            code evaluation state\n          </td>\n          <td>\n            Any state needed to perform, suspend, and resume evaluation of the code associated with this execution context.\n          </td>\n        </tr>\n        <tr>\n          <td>\n            Function\n          </td>\n          <td>\n            If this execution context is evaluating the code of a <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function object</a></emu-xref>, then the value of this component is that <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function object</a></emu-xref>. If the context is evaluating the code of a <emu-nt><a href=\"/ecmascript-language-scripts-and-modules#prod-Script\">Script</a></emu-nt> or <emu-nt><a href=\"/ecmascript-language-scripts-and-modules#prod-Module\">Module</a></emu-nt>, the value is <emu-val>null</emu-val>.\n          </td>\n        </tr>\n        <tr>\n          <td>\n            <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">Realm</a></emu-xref>\n          </td>\n          <td>\n            The <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref> from which associated code accesses ECMAScript resources.\n          </td>\n        </tr>\n        <tr>\n          <td>\n            ScriptOrModule\n          </td>\n          <td>\n            The <emu-xref href=\"/ecmascript-language-scripts-and-modules#sec-abstract-module-records\"><a href=\"/ecmascript-language-scripts-and-modules#sec-abstract-module-records\">Module Record</a></emu-xref> or <emu-xref href=\"/ecmascript-language-scripts-and-modules#script-record\"><a href=\"/ecmascript-language-scripts-and-modules#script-record\">Script Record</a></emu-xref> from which associated code originates. If there is no originating script or module, as is the case for the original execution context created in <emu-xref aoid=\"InitializeHostDefinedRealm\"><a href=\"/executable-code-and-execution-contexts#sec-initializehostdefinedrealm\">InitializeHostDefinedRealm</a></emu-xref>, the value is <emu-val>null</emu-val>.\n          </td>\n        </tr>\n      </table>\n    </emu-table>\n    <p><emu-xref aoid=\"Evaluation\"><a href=\"/syntax-directed-operations#sec-evaluation\">Evaluation</a></emu-xref> of code by the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> may be suspended at various points defined within this specification. Once the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> has been suspended a different execution context may become the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> and commence evaluating its code. At some later time a suspended execution context may again become the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> and continue evaluating its code at the point where it had previously been suspended. Transition of the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> status among execution contexts usually occurs in stack-like last-in/first-out manner. However, some ECMAScript features require non-LIFO transitions of the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>.</p>\n    <p>The value of the <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">Realm</a></emu-xref> component of the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> is also called <dfn id=\"current-realm\">the current Realm Record</dfn>. The value of the Function component of the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> is also called the <dfn id=\"active-function-object\">active function object</dfn>.</p>\n    <p><dfn id=\"ecmascript-code-execution-context\" variants=\"ECMAScript code execution context\">ECMAScript code execution contexts</dfn> have the additional state components listed in <emu-xref href=\"#table-additional-state-components-for-ecmascript-code-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#table-additional-state-components-for-ecmascript-code-execution-contexts\">Table 21</a></emu-xref>.</p>\n    <emu-table id=\"table-additional-state-components-for-ecmascript-code-execution-contexts\" caption=\"Additional State Components for ECMAScript Code Execution Contexts\" oldids=\"table-23\" data-num=\"21\">\n      <table>\n        <thead>\n          <tr>\n            <th>\n              Component\n            </th>\n            <th>\n              Purpose\n            </th>\n          </tr>\n        </thead>\n        <tr>\n          <td>\n            LexicalEnvironment\n          </td>\n          <td>\n            Identifies the <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> used to resolve identifier references made by code within this execution context.\n          </td>\n        </tr>\n        <tr>\n          <td>\n            VariableEnvironment\n          </td>\n          <td>\n            Identifies the <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> that holds bindings created by <emu-nt><a href=\"/ecmascript-language-statements-and-declarations#prod-VariableStatement\">VariableStatement</a></emu-nt>s within this execution context.\n          </td>\n        </tr>\n        <tr>\n          <td>\n            PrivateEnvironment\n          </td>\n          <td>\n            Identifies the <emu-xref href=\"/executable-code-and-execution-contexts#privateenvironment-record\"><a href=\"/executable-code-and-execution-contexts#privateenvironment-record\">PrivateEnvironment Record</a></emu-xref> that holds <emu-xref href=\"/ecmascript-data-types-and-values#sec-private-names\"><a href=\"/ecmascript-data-types-and-values#sec-private-names\">Private Names</a></emu-xref> created by <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-ClassElement\">ClassElement</a></emu-nt>s in the nearest containing class. <emu-val>null</emu-val> if there is no containing class.\n          </td>\n        </tr>\n      </table>\n    </emu-table>\n    <p>The LexicalEnvironment and VariableEnvironment components of an execution context are always <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Records</a></emu-xref>.</p>\n    <p>Execution contexts representing the evaluation of Generators have the additional state components listed in <emu-xref href=\"#table-additional-state-components-for-generator-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#table-additional-state-components-for-generator-execution-contexts\">Table 22</a></emu-xref>.</p>\n    <emu-table id=\"table-additional-state-components-for-generator-execution-contexts\" caption=\"Additional State Components for Generator Execution Contexts\" oldids=\"table-24\" data-num=\"22\">\n      <table>\n        <thead>\n          <tr>\n            <th>\n              Component\n            </th>\n            <th>\n              Purpose\n            </th>\n          </tr>\n        </thead>\n        <tr>\n          <td>\n            Generator\n          </td>\n          <td>\n            The Generator that this execution context is evaluating.\n          </td>\n        </tr>\n      </table>\n    </emu-table>\n    <p>In most situations only the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> (the top of the <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref>) is directly manipulated by algorithms within this specification. Hence when the terms “LexicalEnvironment”, and “VariableEnvironment” are used without qualification they are in reference to those components of the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>.</p>\n    <p>An execution context is purely a specification mechanism and need not correspond to any particular artefact of an ECMAScript implementation. It is impossible for ECMAScript code to directly access or observe an execution context.</p>\n\n    ","5":"<p>A <dfn id=\"job\" variants=\"Jobs\">Job</dfn> is an <emu-xref href=\"/ecmascript-data-types-and-values#sec-abstract-closure\"><a href=\"/ecmascript-data-types-and-values#sec-abstract-closure\">Abstract Closure</a></emu-xref> with no parameters that initiates an ECMAScript computation when no other ECMAScript computation is currently in progress.</p>\n    <p><emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Jobs</a></emu-xref> are scheduled for execution by ECMAScript <emu-xref href=\"/overview#host-environment\"><a href=\"/overview#host-environment\">host environments</a></emu-xref> in a particular <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>. This specification describes the <emu-xref href=\"/overview#host-hook\"><a href=\"/overview#host-hook\">host hooks</a></emu-xref> <emu-xref aoid=\"HostEnqueueGenericJob\"><a href=\"/executable-code-and-execution-contexts#sec-hostenqueuegenericjob\">HostEnqueueGenericJob</a></emu-xref>, <emu-xref aoid=\"HostEnqueueFinalizationRegistryCleanupJob\"><a href=\"/executable-code-and-execution-contexts#sec-host-cleanup-finalization-registry\">HostEnqueueFinalizationRegistryCleanupJob</a></emu-xref>, <emu-xref aoid=\"HostEnqueuePromiseJob\"><a href=\"/executable-code-and-execution-contexts#sec-hostenqueuepromisejob\">HostEnqueuePromiseJob</a></emu-xref>, and <emu-xref aoid=\"HostEnqueueTimeoutJob\"><a href=\"/executable-code-and-execution-contexts#sec-hostenqueuetimeoutjob\">HostEnqueueTimeoutJob</a></emu-xref> to schedule jobs. The <emu-xref href=\"/overview#host-hook\"><a href=\"/overview#host-hook\">host hooks</a></emu-xref> in this specification are organized by the additional constraints imposed on the scheduling of jobs. <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">Hosts</a></emu-xref> may define additional <emu-xref href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\"><a href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\">abstract operations</a></emu-xref> which schedule jobs. Such operations accept a <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-abstract-closure\"><a href=\"/ecmascript-data-types-and-values#sec-abstract-closure\">Abstract Closure</a></emu-xref> and a <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref> (a <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref> or <emu-val>null</emu-val>) as parameters. If a <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref> is provided, these operations schedule the job to be performed at some future time in the provided <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref>, in the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> that owns the <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref>. If <emu-val>null</emu-val> is provided instead for the <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref>, then the job does not evaluate ECMAScript code. Their implementations must conform to the following requirements:</p>\n\n    <ul>\n      <li>At some future point in time, when there is no running context in the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> for which the job is scheduled and that <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>'s <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref> is empty, the implementation must:\n        <ol>\n          <li>Perform any <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> preparation steps.</li>\n          <li><emu-not-ref>Invoke</emu-not-ref> the <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-abstract-closure\"><a href=\"/ecmascript-data-types-and-values#sec-abstract-closure\">Abstract Closure</a></emu-xref>.</li>\n          <li>Perform any <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> cleanup steps, after which the <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref> must be empty.</li>\n        </ol>\n      </li>\n      <li>Only one <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref> may be actively undergoing evaluation at any point in time in an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>.</li>\n      <li>Once evaluation of a <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref> starts, it must run to completion before evaluation of any other <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref> starts in an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>.</li>\n      <li>The <emu-xref href=\"/ecmascript-data-types-and-values#sec-abstract-closure\"><a href=\"/ecmascript-data-types-and-values#sec-abstract-closure\">Abstract Closure</a></emu-xref> must return a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion</a></emu-xref>, implementing its own handling of errors.</li>\n    </ul>\n\n    <emu-note data-num=\"1\"><span class=\"note\">Note 1</span><div class=\"note-contents\">\n      <emu-xref href=\"/overview#host-environment\"><a href=\"/overview#host-environment\">Host environments</a></emu-xref> are not required to treat <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Jobs</a></emu-xref> uniformly with respect to scheduling. For example, web browsers and Node.js treat Promise-handling <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Jobs</a></emu-xref> as a higher priority than other work; future features may add <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Jobs</a></emu-xref> that are not treated at such a high priority.\n    </div></emu-note>\n\n    <p>At any particular time, <var>scriptOrModule</var> (a <emu-xref href=\"/ecmascript-language-scripts-and-modules#script-record\"><a href=\"/ecmascript-language-scripts-and-modules#script-record\">Script Record</a></emu-xref>, a <emu-xref href=\"/ecmascript-language-scripts-and-modules#sec-abstract-module-records\"><a href=\"/ecmascript-language-scripts-and-modules#sec-abstract-module-records\">Module Record</a></emu-xref>, or <emu-val>null</emu-val>) is the <dfn id=\"job-activescriptormodule\">active script or module</dfn> if all of the following conditions are true:</p>\n    <ul>\n      <li><emu-xref aoid=\"GetActiveScriptOrModule\"><a href=\"/executable-code-and-execution-contexts#sec-getactivescriptormodule\">GetActiveScriptOrModule</a></emu-xref>() is <var>scriptOrModule</var>.</li>\n      <li>If <var>scriptOrModule</var> is a <emu-xref href=\"/ecmascript-language-scripts-and-modules#script-record\"><a href=\"/ecmascript-language-scripts-and-modules#script-record\">Script Record</a></emu-xref> or <emu-xref href=\"/ecmascript-language-scripts-and-modules#sec-abstract-module-records\"><a href=\"/ecmascript-language-scripts-and-modules#sec-abstract-module-records\">Module Record</a></emu-xref>, let <var>executionContext</var> be the topmost <emu-xref href=\"/executable-code-and-execution-contexts#sec-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#sec-execution-contexts\">execution context</a></emu-xref> on the <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref> whose ScriptOrModule component is <var>scriptOrModule</var>. The <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">Realm</a></emu-xref> component of <var>executionContext</var> is <var>scriptOrModule</var>.<var class=\"field\">[[Realm]]</var>.</li>\n    </ul>\n\n    <p>At any particular time, an execution is <dfn id=\"job-preparedtoevaluatecode\">prepared to evaluate ECMAScript code</dfn> if all of the following conditions are true:</p>\n    <ul>\n      <li>The <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref> is not empty.</li>\n      <li>The <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">Realm</a></emu-xref> component of the topmost <emu-xref href=\"/executable-code-and-execution-contexts#sec-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#sec-execution-contexts\">execution context</a></emu-xref> on the <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref> is a <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref>.</li>\n    </ul>\n\n    <emu-note data-num=\"2\"><span class=\"note\">Note 2</span><div class=\"note-contents\">\n      <p><emu-xref href=\"/overview#host-environment\"><a href=\"/overview#host-environment\">Host environments</a></emu-xref> may prepare an execution to evaluate code by pushing <emu-xref href=\"/executable-code-and-execution-contexts#sec-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#sec-execution-contexts\">execution contexts</a></emu-xref> onto the <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref>. The specific steps are <emu-xref href=\"/overview#implementation-defined\"><a href=\"/overview#implementation-defined\">implementation-defined</a></emu-xref>.</p>\n      <p>The specific choice of <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">Realm</a></emu-xref> is up to the <emu-xref href=\"/overview#host-environment\"><a href=\"/overview#host-environment\">host environment</a></emu-xref>. This initial <emu-xref href=\"/executable-code-and-execution-contexts#sec-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#sec-execution-contexts\">execution context</a></emu-xref> and <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">Realm</a></emu-xref> is only in use before any callback function is invoked. When a callback function related to a <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref>, like a Promise handler, is invoked, the invocation pushes its own <emu-xref href=\"/executable-code-and-execution-contexts#sec-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#sec-execution-contexts\">execution context</a></emu-xref> and <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">Realm</a></emu-xref>.</p>\n    </div></emu-note>\n\n    <p>Particular kinds of <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Jobs</a></emu-xref> have additional conformance requirements.</p>\n\n    ","6":"<p>An <dfn id=\"agent\" variants=\"agents\">agent</dfn> comprises a set of ECMAScript <emu-xref href=\"/executable-code-and-execution-contexts#sec-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#sec-execution-contexts\">execution contexts</a></emu-xref>, an <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref>, a <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>, an <dfn id=\"agent-record\" variants=\"Agent Records\">Agent Record</dfn>, and an <dfn id=\"executing-thread\" variants=\"executing threads\">executing thread</dfn>. Except for the <emu-xref href=\"/executable-code-and-execution-contexts#executing-thread\"><a href=\"/executable-code-and-execution-contexts#executing-thread\">executing thread</a></emu-xref>, the constituents of an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> belong exclusively to that <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>.</p>\n    <p>An <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>'s <emu-xref href=\"/executable-code-and-execution-contexts#executing-thread\"><a href=\"/executable-code-and-execution-contexts#executing-thread\">executing thread</a></emu-xref> executes algorithmic steps on the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>'s <emu-xref href=\"/executable-code-and-execution-contexts#sec-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#sec-execution-contexts\">execution contexts</a></emu-xref> independently of other <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref>, except that an <emu-xref href=\"/executable-code-and-execution-contexts#executing-thread\"><a href=\"/executable-code-and-execution-contexts#executing-thread\">executing thread</a></emu-xref> may be used as the <emu-xref href=\"/executable-code-and-execution-contexts#executing-thread\"><a href=\"/executable-code-and-execution-contexts#executing-thread\">executing thread</a></emu-xref> by multiple <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref>, provided none of the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> sharing the thread have an <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Record</a></emu-xref> whose <var class=\"field\">[[CanBlock]]</var> field is <emu-val>true</emu-val>.</p>\n    <emu-note data-num=\"1\"><span class=\"note\">Note 1</span><div class=\"note-contents\">\n      <p>Some web browsers share a single <emu-xref href=\"/executable-code-and-execution-contexts#executing-thread\"><a href=\"/executable-code-and-execution-contexts#executing-thread\">executing thread</a></emu-xref> across multiple unrelated tabs of a browser window, for example.</p>\n    </div></emu-note>\n    <p>While an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>'s <emu-xref href=\"/executable-code-and-execution-contexts#executing-thread\"><a href=\"/executable-code-and-execution-contexts#executing-thread\">executing thread</a></emu-xref> is executing algorithmic steps, the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> is the <dfn id=\"surrounding-agent\" variants=\"surrounding agents\">surrounding agent</dfn> for those steps. The steps use the <emu-xref href=\"/executable-code-and-execution-contexts#surrounding-agent\"><a href=\"/executable-code-and-execution-contexts#surrounding-agent\">surrounding agent</a></emu-xref> to access the specification-level execution objects held within the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>: the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>, the <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref>, and the <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Record</a></emu-xref>'s fields.</p>\n    <p>An <dfn variants=\"agent signifiers\">agent signifier</dfn> is a globally-unique opaque value used to identify an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">Agent</a></emu-xref>.</p>\n    <emu-table id=\"table-agent-record\" caption=\"Agent Record Fields\" data-num=\"24\">\n      <table>\n        <thead>\n          <tr>\n            <th>Field Name</th>\n            <th>Value</th>\n            <th>Meaning</th>\n          </tr>\n        </thead>\n        <tr>\n          <td><var class=\"field\">[[LittleEndian]]</var></td>\n          <td>a Boolean</td>\n          <td>The default value computed for the <em>isLittleEndian</em> parameter when it is needed by the algorithms <emu-xref aoid=\"GetValueFromBuffer\"><a href=\"/structured-data#sec-getvaluefrombuffer\">GetValueFromBuffer</a></emu-xref> and <emu-xref aoid=\"SetValueInBuffer\"><a href=\"/structured-data#sec-setvalueinbuffer\">SetValueInBuffer</a></emu-xref>. The choice is <emu-xref href=\"/overview#implementation-defined\"><a href=\"/overview#implementation-defined\">implementation-defined</a></emu-xref> and should be the alternative that is most efficient for the implementation.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[CanBlock]]</var></td>\n          <td>a Boolean</td>\n          <td>Determines whether the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> can block or not.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[Signifier]]</var></td>\n          <td>an agent signifier</td>\n          <td>Uniquely identifies the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> within its <emu-xref href=\"/executable-code-and-execution-contexts#sec-agent-clusters\"><a href=\"/executable-code-and-execution-contexts#sec-agent-clusters\">agent cluster</a></emu-xref>.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[IsLockFree1]]</var></td>\n          <td>a Boolean</td>\n          <td><emu-val>true</emu-val> if atomic operations on one-<emu-not-ref>byte values</emu-not-ref> are lock-free, <emu-val>false</emu-val> otherwise.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[IsLockFree2]]</var></td>\n          <td>a Boolean</td>\n          <td><emu-val>true</emu-val> if atomic operations on two-<emu-not-ref>byte values</emu-not-ref> are lock-free, <emu-val>false</emu-val> otherwise.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[IsLockFree8]]</var></td>\n          <td>a Boolean</td>\n          <td><emu-val>true</emu-val> if atomic operations on eight-<emu-not-ref>byte values</emu-not-ref> are lock-free, <emu-val>false</emu-val> otherwise.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[CandidateExecution]]</var></td>\n          <td>a <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref></td>\n          <td>See the <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref>.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[KeptAlive]]</var></td>\n          <td>a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of either Objects or Symbols</td>\n          <td>Initially a new empty <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref>, representing the list of objects and/or symbols to be kept alive until the end of the current <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref></td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[ModuleAsyncEvaluationCount]]</var></td>\n          <td>an <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integer</a></emu-xref></td>\n          <td>Initially 0, used to assign unique incrementing values to the <var class=\"field\">[[AsyncEvaluationOrder]]</var> field of modules that are asynchronous or have asynchronous dependencies.</td>\n        </tr>\n        <tr>\n          <td><var class=\"field\">[[GlobalSymbolRegistry]]</var></td>\n          <td>a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/fundamental-objects#sec-globalsymbolregistry-records\"><a href=\"/fundamental-objects#sec-globalsymbolregistry-records\">GlobalSymbolRegistry Records</a></emu-xref></td>\n          <td>Initially a new empty <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref>, representing the list of Symbol values produced by <emu-xref href=\"#sec-symbol.for\"><a href=\"/fundamental-objects#sec-symbol.for\">Symbol.for</a></emu-xref>.</td>\n        </tr>\n      </table>\n    </emu-table>\n\n    <p>The values of <var class=\"field\">[[LittleEndian]]</var>, <var class=\"field\">[[Signifier]]</var>, <var class=\"field\">[[IsLockFree1]]</var>, <var class=\"field\">[[IsLockFree2]]</var>, and <var class=\"field\">[[IsLockFree8]]</var> cannot change.</p>\n\n    <p>The <var class=\"field\">[[GlobalSymbolRegistry]]</var> <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> is append-only and never reassigned.</p>\n\n    <emu-note data-num=\"2\"><span class=\"note\">Note 2</span><div class=\"note-contents\">\n      <p>The values of <var class=\"field\">[[IsLockFree1]]</var>, <var class=\"field\">[[IsLockFree2]]</var>, and <var class=\"field\">[[IsLockFree8]]</var> are not necessarily determined by the hardware, but may also reflect implementation choices that can vary over time and between ECMAScript implementations.</p>\n\n      <p>There is no <var class=\"field\">[[IsLockFree4]]</var> field: 4-byte atomic operations are always lock-free.</p>\n\n      <p>In practice, if an atomic operation is implemented with any type of lock the operation is not lock-free. Lock-free does not imply wait-free: there is no upper bound on how many machine steps may be required to complete a lock-free atomic operation.</p>\n\n      <p>That an atomic access of size <em>n</em> is lock-free does not imply anything about the (perceived) atomicity of non-atomic accesses of size <em>n</em>, specifically, non-atomic accesses may still be performed as a sequence of several separate memory accesses. See <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">ReadSharedMemory</a></emu-xref> and <emu-xref href=\"/memory-model#sec-memory-model-fundamentals\"><a href=\"/memory-model#sec-memory-model-fundamentals\">WriteSharedMemory</a></emu-xref> for details.</p>\n    </div></emu-note>\n\n    <emu-note data-num=\"3\"><span class=\"note\">Note 3</span><div class=\"note-contents\">\n      <p>An <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> is a specification mechanism and need not correspond to any particular artefact of an ECMAScript implementation.</p>\n    </div></emu-note>\n\n    ","7":"<p>An <dfn variants=\"agent clusters\">agent cluster</dfn> is a maximal set of <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> that can communicate by operating on shared memory.</p>\n\n    <emu-note data-num=\"1\"><span class=\"note\">Note 1</span><div class=\"note-contents\">\n      <p>Programs within different <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> may share memory by unspecified means. At a minimum, the backing memory for SharedArrayBuffers can be shared among the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> in the cluster.</p>\n\n      <p>There may be <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> that can communicate by message passing that cannot share memory; they are never in the same agent cluster.</p>\n    </div></emu-note>\n\n    <p>Every <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> belongs to exactly one agent cluster.</p>\n\n    <emu-note data-num=\"2\"><span class=\"note\">Note 2</span><div class=\"note-contents\">\n      <p>The <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> in a cluster need not all be alive at some particular point in time. If <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> <b>A</b> creates another <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> <b>B</b>, after which <b>A</b> terminates and <b>B</b> creates <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> <b>C</b>, the three <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> are in the same cluster if <b>A</b> could share some memory with <b>B</b> and <b>B</b> could share some memory with <b>C</b>.</p>\n    </div></emu-note>\n\n    <p>All <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> within a cluster must have the same value for the <var class=\"field\">[[LittleEndian]]</var> field in their respective <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Records</a></emu-xref>.</p>\n\n    <emu-note data-num=\"3\"><span class=\"note\">Note 3</span><div class=\"note-contents\">\n      <p>If different <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> within an agent cluster have different values of <var class=\"field\">[[LittleEndian]]</var> it becomes hard to use shared memory for multi-byte data.</p>\n    </div></emu-note>\n\n    <p>All <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> within a cluster must have the same values for the <var class=\"field\">[[IsLockFree1]]</var> field in their respective <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Records</a></emu-xref>; similarly for the <var class=\"field\">[[IsLockFree2]]</var> and <var class=\"field\">[[IsLockFree8]]</var> fields.</p>\n\n    <p>All <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> within a cluster must have different values for the <var class=\"field\">[[Signifier]]</var> field in their respective <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Records</a></emu-xref>.</p>\n\n    <p>An embedding may deactivate (stop forward progress) or activate (resume forward progress) an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> without the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>'s knowledge or cooperation. If the embedding does so, it must not leave some <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> in the cluster active while other <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> in the cluster are deactivated indefinitely.</p>\n\n    <emu-note data-num=\"4\"><span class=\"note\">Note 4</span><div class=\"note-contents\">\n      <p>The purpose of the preceding restriction is to avoid a situation where an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> deadlocks or starves because another <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> has been deactivated. For example, if an HTML shared worker that has a lifetime independent of documents in any windows were allowed to share memory with the dedicated worker of such an independent document, and the document and its dedicated worker were to be deactivated while the dedicated worker holds a lock (say, the document is pushed into its window's history), and the shared worker then tries to acquire the lock, then the shared worker will be blocked until the dedicated worker is activated again, if ever. Meanwhile other workers trying to access the shared worker from other windows will starve.</p>\n\n      <p>The implication of the restriction is that it will not be possible to share memory between <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> that don't belong to the same suspend/wake collective within the embedding.</p>\n    </div></emu-note>\n\n    <p>An embedding may terminate an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> without any of the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>'s cluster's other <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref>' prior knowledge or cooperation. If an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> is terminated not by programmatic action of its own or of another <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> in the cluster but by forces external to the cluster, then the embedding must choose one of two strategies: Either terminate all the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> in the cluster, or provide reliable APIs that allow the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> in the cluster to coordinate so that at least one remaining member of the cluster will be able to detect the termination, with the termination data containing enough information to identify the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> that was terminated.</p>\n\n    <emu-note data-num=\"5\"><span class=\"note\">Note 5</span><div class=\"note-contents\">\n      <p>Examples of that type of termination are: operating systems or users terminating <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> that are running in separate processes; the embedding itself terminating an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> that is running in-process with the other <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> when per-<emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> resource accounting indicates that the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> is runaway.</p>\n    </div></emu-note>\n\n    <p>Each of the following specification values, and values transitively reachable from them, belong to exactly one agent cluster.</p>\n    <ul>\n      <li><emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref></li>\n      <li><emu-xref href=\"/ecmascript-data-types-and-values#sec-data-blocks\"><a href=\"/ecmascript-data-types-and-values#sec-data-blocks\">Shared Data Block</a></emu-xref></li>\n      <li><emu-xref href=\"/structured-data#sec-waiterlist-records\"><a href=\"/structured-data#sec-waiterlist-records\">WaiterList Record</a></emu-xref></li>\n    </ul>\n\n    <p>Prior to any evaluation of any ECMAScript code by any <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> in a cluster, the <var class=\"field\">[[CandidateExecution]]</var> field of the <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Record</a></emu-xref> for all <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> in the cluster is set to the initial <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref>. The initial <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> is an <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">empty candidate execution</a></emu-xref> whose <var class=\"field\">[[EventsRecords]]</var> field is a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> containing, for each <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>, an <emu-xref href=\"/memory-model#sec-agent-event-records\"><a href=\"/memory-model#sec-agent-event-records\">Agent Events Record</a></emu-xref> whose <var class=\"field\">[[AgentSignifier]]</var> field is that <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>'s <emu-xref href=\"/executable-code-and-execution-contexts#sec-agents\"><a href=\"/executable-code-and-execution-contexts#sec-agents\">agent signifier</a></emu-xref>, and whose <var class=\"field\">[[EventList]]</var> and <var class=\"field\">[[AgentSynchronizesWith]]</var> fields are empty <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Lists</a></emu-xref>.</p>\n\n    <emu-note data-num=\"6\"><span class=\"note\">Note 6</span><div class=\"note-contents\">\n      <p>All <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> in an agent cluster share the same <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> in its <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Record</a></emu-xref>'s <var class=\"field\">[[CandidateExecution]]</var> field. The <emu-xref href=\"/memory-model#sec-candidate-executions\"><a href=\"/memory-model#sec-candidate-executions\">candidate execution</a></emu-xref> is a specification mechanism used by the <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref>.</p>\n    </div></emu-note>\n\n    <emu-note data-num=\"7\"><span class=\"note\">Note 7</span><div class=\"note-contents\">\n      <p>An agent cluster is a specification mechanism and need not correspond to any particular artefact of an ECMAScript implementation.</p>\n    </div></emu-note>\n  ","8":"<p>For an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> to <em>make forward progress</em> is for it to perform an evaluation step according to this specification.</p>\n    <p>An <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> becomes <em>blocked</em> when its <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> waits synchronously and indefinitely for an external event. Only <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> whose <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Record</a></emu-xref>'s <var class=\"field\">[[CanBlock]]</var> field is <emu-val>true</emu-val> can become blocked in this sense. An <em>unblocked</em> <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> is one that is not blocked.</p>\n\n    <p>Implementations must ensure that:</p>\n    <ul>\n      <li>every unblocked <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> with a dedicated <emu-xref href=\"/executable-code-and-execution-contexts#executing-thread\"><a href=\"/executable-code-and-execution-contexts#executing-thread\">executing thread</a></emu-xref> eventually makes forward progress</li>\n      <li>in a set of <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref> that share an <emu-xref href=\"/executable-code-and-execution-contexts#executing-thread\"><a href=\"/executable-code-and-execution-contexts#executing-thread\">executing thread</a></emu-xref>, one <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> eventually makes forward progress</li>\n      <li>an <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> does not cause another <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> to become blocked except via explicit APIs that provide blocking.</li>\n    </ul>\n\n    <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n      <p>This, along with the liveness guarantee in the <emu-xref href=\"/memory-model#sec-memory-model\"><a href=\"/memory-model#sec-memory-model\">memory model</a></emu-xref>, ensures that all <emu-const>seq-cst</emu-const> writes eventually become observable to all <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agents</a></emu-xref>.</p>\n    </div></emu-note>\n  ","9":"","10":"<p>The abstract operation ClearKeptObjects takes no arguments and returns <emu-const>unused</emu-const>. ECMAScript implementations are expected to call ClearKeptObjects when a synchronous sequence of ECMAScript executions completes. It performs the following steps when called:</p>\n    <emu-alg><ol><li>Let <var>agentRecord</var> be the <emu-xref href=\"/executable-code-and-execution-contexts#surrounding-agent\"><a href=\"/executable-code-and-execution-contexts#surrounding-agent\">surrounding agent</a></emu-xref>'s <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Record</a></emu-xref>.</li><li>Set <var>agentRecord</var>.<var class=\"field\">[[KeptAlive]]</var> to a new empty <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref>.</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n  ","11":"<p>The abstract operation AddToKeptObjects takes argument <var>value</var> (an Object or a Symbol) and returns <emu-const>unused</emu-const>. It performs the following steps when called:</p>\n    <emu-alg><ol><li>Let <var>agentRecord</var> be the <emu-xref href=\"/executable-code-and-execution-contexts#surrounding-agent\"><a href=\"/executable-code-and-execution-contexts#surrounding-agent\">surrounding agent</a></emu-xref>'s <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Record</a></emu-xref>.</li><li>Append <var>value</var> to <var>agentRecord</var>.<var class=\"field\">[[KeptAlive]]</var>.</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n    <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n      When the abstract operation AddToKeptObjects is called with a target object or symbol, it adds the target to a list that will point strongly at the target until <emu-xref aoid=\"ClearKeptObjects\"><a href=\"/executable-code-and-execution-contexts#sec-clear-kept-objects\">ClearKeptObjects</a></emu-xref> is called.\n    </div></emu-note>\n  ","12":"<p>The abstract operation CleanupFinalizationRegistry takes argument <var>finalizationRegistry</var> (a <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistry</a></emu-xref>) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It performs the following steps when called:</p>\n    <emu-alg><ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>finalizationRegistry</var> has <var class=\"field\">[[Cells]]</var> and <var class=\"field\">[[CleanupCallback]]</var> internal slots.</li><li>Let <var>callback</var> be <var>finalizationRegistry</var>.<var class=\"field\">[[CleanupCallback]]</var>.</li><li>While <var>finalizationRegistry</var>.<var class=\"field\">[[Cells]]</var> contains a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref> <var>cell</var> such that <var>cell</var>.<var class=\"field\">[[WeakRefTarget]]</var> is <emu-const>empty</emu-const>, an implementation may perform the following steps:<ol><li>Choose any such <var>cell</var>.</li><li>Remove <var>cell</var> from <var>finalizationRegistry</var>.<var class=\"field\">[[Cells]]</var>.</li><li>Perform ? <emu-xref aoid=\"HostCallJobCallback\"><a href=\"/executable-code-and-execution-contexts#sec-hostcalljobcallback\">HostCallJobCallback</a></emu-xref>(<var>callback</var>, <emu-val>undefined</emu-val>, « <var>cell</var>.<var class=\"field\">[[HeldValue]]</var> »).</li></ol></li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n  ","13":"<p>The abstract operation CanBeHeldWeakly takes argument <var>arg</var> (an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref>) and returns a Boolean. It returns <emu-val>true</emu-val> if and only if <var>arg</var> is suitable for use as a weak reference. Only values that are suitable for use as a weak reference may be a key of a WeakMap, an element of a WeakSet, the target of a <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref>, or one of the targets of a <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistry</a></emu-xref>. It performs the following steps when called:</p>\n    <emu-alg><ol><li class=\"exit\">If <var>arg</var> <emu-xref href=\"/ecmascript-data-types-and-values#sec-object-type\"><a href=\"/ecmascript-data-types-and-values#sec-object-type\">is an Object</a></emu-xref>, return <emu-val>true</emu-val>.</li><li class=\"exit\">If <var>arg</var> <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types-symbol-type\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types-symbol-type\">is a Symbol</a></emu-xref> and <emu-xref aoid=\"KeyForSymbol\"><a href=\"/fundamental-objects#sec-keyforsymbol\">KeyForSymbol</a></emu-xref>(<var>arg</var>) is <emu-val>undefined</emu-val>, return <emu-val>true</emu-val>.</li><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></emu-alg>\n    <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n      <p>A language value without <emu-xref href=\"#sec-identity\"><a href=\"/notational-conventions#sec-identity\">language identity</a></emu-xref> can be manifested without prior reference and is unsuitable for use as a weak reference. A Symbol value produced by <emu-xref href=\"#sec-symbol.for\"><a href=\"/fundamental-objects#sec-symbol.for\">Symbol.for</a></emu-xref>, unlike other Symbol values, does not have language identity and is unsuitable for use as a weak reference. <emu-xref href=\"#sec-well-known-symbols\"><a href=\"/ecmascript-data-types-and-values#sec-well-known-symbols\">Well-known symbols</a></emu-xref> are likely to never be collected, but are nonetheless treated as suitable for use as a weak reference because they are limited in number and therefore manageable by a variety of implementation approaches. However, any value associated to a well-known symbol in a <emu-xref href=\"/executable-code-and-execution-contexts#sec-liveness\"><a href=\"/executable-code-and-execution-contexts#sec-liveness\">live</a></emu-xref> WeakMap is unlikely to be collected and could “leak” memory resources in implementations.</p>\n    </div></emu-note>\n  ","":"","1.1":"<p><emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Records</a></emu-xref> can be thought of as existing in a simple object-oriented hierarchy where <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> is an abstract class with three concrete subclasses: <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref>, <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref>, and <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref>. <emu-xref href=\"/executable-code-and-execution-contexts#sec-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-function-environment-records\">Function Environment Records</a></emu-xref> and <emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Records</a></emu-xref> are subclasses of <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref>.</p>\n      <ul>\n        <li>\n          <p><emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> (abstract)</p>\n          <ul>\n            <li>\n              <p>A <em><emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref></em> is used to define the effect of ECMAScript language syntactic elements such as <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-FunctionDeclaration\">FunctionDeclaration</a></emu-nt>s, <emu-nt><a href=\"/ecmascript-language-statements-and-declarations#prod-VariableDeclaration\">VariableDeclaration</a></emu-nt>s, and <emu-nt><a href=\"/ecmascript-language-statements-and-declarations#prod-Catch\">Catch</a></emu-nt> clauses that directly associate identifier bindings with <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language values</a></emu-xref>.</p>\n              <ul>\n                <li>\n                  <p>A <em><emu-xref href=\"/executable-code-and-execution-contexts#sec-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-function-environment-records\">Function Environment Record</a></emu-xref></em> corresponds to the invocation of an ECMAScript <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function object</a></emu-xref>, and contains bindings for the top-level declarations within that function. It may establish a new <code>this</code> binding. It also captures the state necessary to support <code>super</code> method invocations.</p>\n                </li>\n                <li>\n                  <p>A <em><emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Record</a></emu-xref></em> contains the bindings for the top-level declarations of a <emu-nt><a href=\"/ecmascript-language-scripts-and-modules#prod-Module\">Module</a></emu-nt>. It also contains the bindings that are explicitly imported by the <emu-nt><a href=\"/ecmascript-language-scripts-and-modules#prod-Module\">Module</a></emu-nt>. Its <var class=\"field\">[[OuterEnv]]</var> is a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref>.</p>\n                </li>\n              </ul>\n            </li>\n            <li>\n              <p>An <em><emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref></em> is used to define the effect of ECMAScript elements such as <emu-nt><a href=\"/ecmascript-language-statements-and-declarations#prod-WithStatement\">WithStatement</a></emu-nt> that associate identifier bindings with the properties of some object.</p>\n            </li>\n            <li>\n              <p>A <em><emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref></em> is used for <emu-nt><a href=\"/ecmascript-language-scripts-and-modules#prod-Script\">Script</a></emu-nt> global declarations. It does not have an outer environment; its <var class=\"field\">[[OuterEnv]]</var> is <emu-val>null</emu-val>. It may be prepopulated with identifier bindings and it includes an associated <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref> whose properties provide some of the global environment's identifier bindings. As ECMAScript code is executed, additional properties may be added to the <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref> and the initial properties may be modified.</p>\n            </li>\n          </ul>\n        </li>\n      </ul>\n\n      <p>The <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> abstract class includes the abstract specification methods defined in <emu-xref href=\"#table-abstract-methods-of-environment-records\"><a href=\"/executable-code-and-execution-contexts#table-abstract-methods-of-environment-records\">Table 14</a></emu-xref>. These abstract methods have distinct concrete algorithms for each of the concrete subclasses.</p>\n      <emu-table id=\"table-abstract-methods-of-environment-records\" type=\"abstract methods\" of=\"Environment Records\" oldids=\"table-15,table-17,table-19,table-20,table-additional-methods-of-function-environment-records,table-additional-methods-of-global-environment-records,table-additional-methods-of-module-environment-records\" data-num=\"14\">\n        <table>\n          <thead>\n            <tr>\n              <th>\n                Method\n              </th>\n              <th>\n                Purpose\n              </th>\n              <th>\n                Definitions\n              </th>\n            </tr>\n          </thead>\n          <tr id=\"abstract-hasbinding\">\n            <td>\n              HasBinding (\n                <var>name</var>: a String,\n              ): either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a Boolean or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>\n            </td>\n            <td>\n              It determines if an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> has a binding for <var>name</var>.\n            </td>\n            <td>\n              It has concrete definitions in the following types:\n              <emu-concrete-method-dfns for=\"HasBinding\"></emu-concrete-method-dfns>\n            </td>\n          </tr>\n          <tr id=\"abstract-createmutablebinding\">\n            <td>\n              CreateMutableBinding (\n                <var>name</var>: a String,\n                <var>deletable</var>: a Boolean,\n              ): either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>\n            </td>\n            <td>\n              It creates a new but uninitialized mutable binding in an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>. <var>name</var> is the text of the bound name. If <var>deletable</var> is <emu-val>true</emu-val> the binding may be subsequently deleted.\n            </td>\n            <td>\n              It has concrete definitions in the following types:\n              <emu-concrete-method-dfns for=\"CreateMutableBinding\"></emu-concrete-method-dfns>\n            </td>\n          </tr>\n          <tr id=\"abstract-createimmutablebinding\">\n            <td>\n              CreateImmutableBinding (\n                <var>name</var>: a String,\n                <var>strict</var>: a Boolean,\n              ): either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>\n            </td>\n            <td>\n              It creates a new but uninitialized immutable binding in an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>. <var>name</var> is the text of the bound name. If <var>strict</var> is <emu-val>true</emu-val> then attempts to set it after it has been initialized will always throw an exception, regardless of the strict mode setting of operations that reference that binding.\n            </td>\n            <td>\n              It has concrete definitions in the following types:\n              <emu-concrete-method-dfns for=\"CreateImmutableBinding\"></emu-concrete-method-dfns>\n            </td>\n          </tr>\n          <tr id=\"abstract-initializebinding\">\n            <td>\n              InitializeBinding (\n                <var>name</var>: a String,\n                <var>value</var>: an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref>,\n              ): either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>\n            </td>\n            <td>\n              It sets the value of an already existing but uninitialized binding in an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>. <var>name</var> is the text of the bound name. <var>value</var> is the value for the binding.\n            </td>\n            <td>\n              It has concrete definitions in the following types:\n              <emu-concrete-method-dfns for=\"InitializeBinding\"></emu-concrete-method-dfns>\n            </td>\n          </tr>\n          <tr id=\"abstract-setmutablebinding\">\n            <td>\n              SetMutableBinding (\n                <var>name</var>: a String,\n                <var>value</var>: an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref>,\n                <var>strict</var>: a Boolean,\n              ): either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>\n            </td>\n            <td>\n              It sets the value of an already existing mutable binding in an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>. <var>name</var> is the text of the bound name. <var>value</var> is the value for the binding. If <var>strict</var> is <emu-val>true</emu-val> and the binding cannot be set, this will throw a <emu-val>TypeError</emu-val> exception.\n            </td>\n            <td>\n              It has concrete definitions in the following types:\n              <emu-concrete-method-dfns for=\"SetMutableBinding\"></emu-concrete-method-dfns>\n            </td>\n          </tr>\n          <tr id=\"abstract-getbindingvalue\">\n            <td>\n              GetBindingValue (\n                <var>name</var>: a String,\n                <var>strict</var>: a Boolean,\n              ): either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>\n            </td>\n            <td>\n              It returns the value of an already existing binding from an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>. <var>name</var> is the text of the bound name. <var>strict</var> is used to identify references originating in <emu-xref href=\"/ecmascript-language-source-code#sec-strict-mode-code\"><a href=\"/ecmascript-language-source-code#sec-strict-mode-code\">strict mode code</a></emu-xref> or that otherwise require strict mode reference semantics. If <var>strict</var> is <emu-val>true</emu-val> and the binding does not exist, this will throw a <emu-val>ReferenceError</emu-val> exception. If the binding exists but is uninitialized a <emu-val>ReferenceError</emu-val> is thrown, regardless of the value of <var>strict</var>.\n            </td>\n            <td>\n              It has concrete definitions in the following types:\n              <emu-concrete-method-dfns for=\"GetBindingValue\"></emu-concrete-method-dfns>\n            </td>\n          </tr>\n          <tr id=\"abstract-deletebinding\">\n            <td>\n              DeleteBinding (\n                <var>name</var>: a String,\n              ): either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a Boolean or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>\n            </td>\n            <td>\n              It deletes a binding from an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>. <var>name</var> is the text of the bound name. If a binding for <var>name</var> exists, this removes the binding and returns <emu-val>true</emu-val>. If the binding exists but cannot be removed, this returns <emu-val>false</emu-val>. If the binding does not exist, this returns <emu-val>true</emu-val>.\n            </td>\n            <td>\n              It has concrete definitions in the following types:\n              <emu-concrete-method-dfns for=\"DeleteBinding\"></emu-concrete-method-dfns>\n            </td>\n          </tr>\n          <tr id=\"abstract-hasthisbinding\">\n            <td>HasThisBinding ( ): a Boolean</td>\n            <td>\n              It determines if an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> establishes a <code>this</code> binding. This returns <emu-val>true</emu-val> if it does and <emu-val>false</emu-val> if it does not.\n            </td>\n            <td>\n              It has concrete definitions in the following types:\n              <emu-concrete-method-dfns for=\"HasThisBinding\"></emu-concrete-method-dfns>\n            </td>\n          </tr>\n          <tr id=\"abstract-getthisbinding\">\n            <td>GetThisBinding ( ): either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref></td>\n            <td>\n              It returns the value of this <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>'s <code>this</code> binding. It throws a <emu-val>ReferenceError</emu-val> if the <code>this</code> binding has not been initialized.\n            </td>\n            <td>\n              It has concrete definitions in the following types:\n              <emu-concrete-method-dfns for=\"GetThisBinding\"></emu-concrete-method-dfns>\n            </td>\n          </tr>\n          <tr id=\"abstract-hassuperbinding\">\n            <td>HasSuperBinding ( ): a Boolean</td>\n            <td>\n              It determines if an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> establishes a <code>super</code> method binding. This returns <emu-val>true</emu-val> if it does and <emu-val>false</emu-val> if it does not. If it returns <emu-val>true</emu-val> it implies that the <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> is a <emu-xref href=\"/executable-code-and-execution-contexts#sec-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-function-environment-records\">Function Environment Record</a></emu-xref>, although the reverse implication does not hold.\n            </td>\n            <td>\n              It has concrete definitions in the following types:\n              <emu-concrete-method-dfns for=\"HasSuperBinding\"></emu-concrete-method-dfns>\n            </td>\n          </tr>\n          <tr id=\"abstract-withbaseobject\">\n            <td>WithBaseObject ( ): an Object or <emu-val>undefined</emu-val></td>\n            <td>\n              If this <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> is associated with a <code>with</code> statement, it returns the with object. Otherwise, it returns <emu-val>undefined</emu-val>.\n            </td>\n            <td>\n              It has concrete definitions in the following types:\n              <emu-concrete-method-dfns for=\"WithBaseObject\"></emu-concrete-method-dfns>\n            </td>\n          </tr>\n        </table>\n      </emu-table>\n\n      ","1.1.1":"<p>Each <dfn variants=\"Declarative Environment Records\">Declarative Environment Record</dfn> is associated with an ECMAScript program scope containing variable, constant, let, class, module, import, and/or function declarations. A Declarative Environment Record binds the set of identifiers defined by the declarations contained within its scope.</p>\n\n        ","1.1.1.1":"<p>The HasBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> <var>envRecord</var> takes argument <var>name</var> (a String) and returns a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a Boolean. It determines if the argument identifier is one of the identifiers bound by the record. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">If <var>envRecord</var> has a binding for <var>name</var>, return <emu-val>true</emu-val>.</li><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></emu-alg>\n        ","1.1.1.2":"<p>The CreateMutableBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String) and <var>deletable</var> (a Boolean) and returns a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const>. It creates a new mutable binding for the name <var>name</var> that is uninitialized. A binding must not already exist in this <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> for <var>name</var>. If <var>deletable</var> is <emu-val>true</emu-val>, the new binding is marked as being subject to deletion. It performs the following steps when called:</p>\n          <emu-alg><ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>envRecord</var> does not already have a binding for <var>name</var>.</li><li>Create a mutable binding in <var>envRecord</var> for <var>name</var> and record that it is uninitialized. If <var>deletable</var> is <emu-val>true</emu-val>, record that the newly created binding may be deleted by a subsequent DeleteBinding call.</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n        ","1.1.1.3":"<p>The CreateImmutableBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String) and <var>strict</var> (a Boolean) and returns a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const>. It creates a new immutable binding for the name <var>name</var> that is uninitialized. A binding must not already exist in this <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> for <var>name</var>. If <var>strict</var> is <emu-val>true</emu-val>, the new binding is marked as a strict binding. It performs the following steps when called:</p>\n          <emu-alg><ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>envRecord</var> does not already have a binding for <var>name</var>.</li><li>Create an immutable binding in <var>envRecord</var> for <var>name</var> and record that it is uninitialized. If <var>strict</var> is <emu-val>true</emu-val>, record that the newly created binding is a strict binding.</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n        ","1.1.1.4":"<p>The InitializeBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String) and <var>value</var> (an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref>) and returns a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const>. It is used to set the bound value of the current binding of the identifier whose name is <var>name</var> to the value <var>value</var>. An uninitialized binding for <var>name</var> must already exist. It performs the following steps when called:</p>\n          <emu-alg><ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>envRecord</var> must have an uninitialized binding for <var>name</var>.</li><li>Set the bound value for <var>name</var> in <var>envRecord</var> to <var>value</var>.</li><li><emu-not-ref>Record</emu-not-ref> that the binding for <var>name</var> in <var>envRecord</var> has been initialized.</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n        ","1.1.1.5":"<p>The SetMutableBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String), <var>value</var> (an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref>), and <var>strict</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It attempts to change the bound value of the current binding of the identifier whose name is <var>name</var> to the value <var>value</var>. A binding for <var>name</var> normally already exists, but in rare cases it may not. If the binding is an immutable binding, a <emu-val>TypeError</emu-val> is thrown if <var>strict</var> is <emu-val>true</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li id=\"step-setmutablebinding-missing-binding\">If <var>envRecord</var> does not have a binding for <var>name</var>, then<ol><li class=\"exit\">If <var>strict</var> is <emu-val>true</emu-val>, throw a <emu-val>ReferenceError</emu-val> exception.</li><li>Perform ! <var>envRecord</var>.CreateMutableBinding(<var>name</var>, <emu-val>true</emu-val>).</li><li>Perform ! <var>envRecord</var>.InitializeBinding(<var>name</var>, <var>value</var>).</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></li><li>If the binding for <var>name</var> in <var>envRecord</var> is a strict binding, set <var>strict</var> to <emu-val>true</emu-val>.</li><li>If the binding for <var>name</var> in <var>envRecord</var> has not yet been initialized, then<ol><li class=\"exit\">Throw a <emu-val>ReferenceError</emu-val> exception.</li></ol></li><li>Else if the binding for <var>name</var> in <var>envRecord</var> is a mutable binding, then<ol><li>Change its bound value to <var>value</var>.</li></ol></li><li>Else,<ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: This is an attempt to change the value of an immutable binding.</li><li class=\"exit\">If <var>strict</var> is <emu-val>true</emu-val>, throw a <emu-val>TypeError</emu-val> exception.</li></ol></li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p>An example of ECMAScript code that results in a missing binding at step <emu-xref href=\"#step-setmutablebinding-missing-binding\"><a href=\"/executable-code-and-execution-contexts#step-setmutablebinding-missing-binding\">1</a></emu-xref> is:</p>\n            <pre><code class=\"hljs javascript\"><span class=\"hljs-keyword\">function</span> <span class=\"hljs-title function_\">f</span>(<span class=\"hljs-params\"></span>) { <span class=\"hljs-built_in\">eval</span>(<span class=\"hljs-string\">&quot;var x; x = (delete x, 0);&quot;</span>); }</code></pre>\n          </div></emu-note>\n        ","1.1.1.6":"<p>The GetBindingValue concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String) and <var>strict</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It returns the value of its bound identifier whose name is <var>name</var>. If the binding exists but is uninitialized a <emu-val>ReferenceError</emu-val> is thrown, regardless of the value of <var>strict</var>. It performs the following steps when called:</p>\n          <emu-alg><ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>envRecord</var> has a binding for <var>name</var>.</li><li class=\"exit\">If the binding for <var>name</var> in <var>envRecord</var> is an uninitialized binding, throw a <emu-val>ReferenceError</emu-val> exception.</li><li class=\"exit\">Return the value currently bound to <var>name</var> in <var>envRecord</var>.</li></ol></emu-alg>\n        ","1.1.1.7":"<p>The DeleteBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> <var>envRecord</var> takes argument <var>name</var> (a String) and returns a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a Boolean. It can only delete bindings that have been explicitly designated as being subject to deletion. It performs the following steps when called:</p>\n          <emu-alg><ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>envRecord</var> has a binding for <var>name</var>.</li><li class=\"exit\">If the binding for <var>name</var> in <var>envRecord</var> cannot be deleted, return <emu-val>false</emu-val>.</li><li>Remove the binding for <var>name</var> from <var>envRecord</var>.</li><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></emu-alg>\n        ","1.1.1.8":"<p>The HasThisBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns <emu-val>false</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p>A regular <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> (i.e., one that is neither a <emu-xref href=\"/executable-code-and-execution-contexts#sec-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-function-environment-records\">Function Environment Record</a></emu-xref> nor a <emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Record</a></emu-xref>) does not provide a <code>this</code> binding.</p>\n          </div></emu-note>\n        ","1.1.1.9":"<p>The GetThisBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> is never used within this specification.</p>\n        ","1.1.1.10":"<p>The HasSuperBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns <emu-val>false</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p>A regular <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> (i.e., one that is neither a <emu-xref href=\"/executable-code-and-execution-contexts#sec-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-function-environment-records\">Function Environment Record</a></emu-xref> nor a <emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Record</a></emu-xref>) does not provide a <code>super</code> binding.</p>\n          </div></emu-note>\n        ","1.1.1.11":"<p>The WithBaseObject concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns <emu-val>undefined</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">Return <emu-val>undefined</emu-val>.</li></ol></emu-alg>\n        ","1.1.2":"<p>Each <dfn variants=\"Object Environment Records\">Object Environment Record</dfn> is associated with an object called its <em>binding object</em>. An Object Environment Record binds the set of string identifier names that directly correspond to the <emu-xref href=\"/ecmascript-data-types-and-values#property-name\"><a href=\"/ecmascript-data-types-and-values#property-name\">property names</a></emu-xref> of its binding object. <emu-xref href=\"/ecmascript-data-types-and-values#property-key\"><a href=\"/ecmascript-data-types-and-values#property-key\">Property keys</a></emu-xref> that are not strings in the form of an <emu-nt><a href=\"/ecmascript-language-lexical-grammar#prod-IdentifierName\">IdentifierName</a></emu-nt> are not included in the set of bound identifiers. Both own and inherited properties are included in the set regardless of the setting of their <var class=\"field\">[[Enumerable]]</var> attribute. Because properties can be dynamically added and deleted from objects, the set of identifiers bound by an Object Environment Record may potentially change as a side-effect of any operation that adds or deletes properties. Any bindings that are created as a result of such a side-effect are considered to be a mutable binding even if the Writable attribute of the corresponding property is <emu-val>false</emu-val>. Immutable bindings do not exist for Object Environment Records.</p>\n        <p>Object Environment Records created for <code>with</code> statements (<emu-xref href=\"#sec-with-statement\"><a href=\"/ecmascript-language-statements-and-declarations#sec-with-statement\">14.11</a></emu-xref>) can provide their binding object as an implicit <emu-val>this</emu-val> value for use in function calls. The capability is controlled by a Boolean <var class=\"field\">[[IsWithEnvironment]]</var> field.</p>\n        <p>Object Environment Records have the additional state fields listed in <emu-xref href=\"#table-additional-fields-of-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#table-additional-fields-of-object-environment-records\">Table 15</a></emu-xref>.</p>\n        <emu-table id=\"table-additional-fields-of-object-environment-records\" caption=\"Additional Fields of Object Environment Records\" data-num=\"15\">\n          <table>\n            <thead>\n              <tr>\n                <th>\n                  Field Name\n                </th>\n                <th>\n                  Value\n                </th>\n                <th>\n                  Meaning\n                </th>\n              </tr>\n            </thead>\n            <tr>\n              <td>\n                <var class=\"field\">[[BindingObject]]</var>\n              </td>\n              <td>\n                an Object\n              </td>\n              <td>\n                The binding object of this <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>.\n              </td>\n            </tr>\n            <tr>\n              <td>\n                <var class=\"field\">[[IsWithEnvironment]]</var>\n              </td>\n              <td>\n                a Boolean\n              </td>\n              <td>\n                Indicates whether this <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> is created for a <code>with</code> statement.\n              </td>\n            </tr>\n          </table>\n        </emu-table>\n\n        ","1.1.2.1":"<p>The HasBinding concrete method of an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> <var>envRecord</var> takes argument <var>name</var> (a String) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a Boolean or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It determines if its associated binding object has a property whose name is <var>name</var>. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>bindingObj</var> be <var>envRecord</var>.<var class=\"field\">[[BindingObject]]</var>.</li><li>Let <var>foundBinding</var> be ? <emu-xref aoid=\"HasProperty\"><a href=\"/abstract-operations#sec-hasproperty\">HasProperty</a></emu-xref>(<var>bindingObj</var>, <var>name</var>).</li><li class=\"exit\">If <var>foundBinding</var> is <emu-val>false</emu-val>, return <emu-val>false</emu-val>.</li><li class=\"exit\">If <var>envRecord</var>.<var class=\"field\">[[IsWithEnvironment]]</var> is <emu-val>false</emu-val>, return <emu-val>true</emu-val>.</li><li>Let <var>unscopables</var> be ? <emu-xref aoid=\"Get\"><a href=\"/abstract-operations#sec-get-o-p\">Get</a></emu-xref>(<var>bindingObj</var>, <emu-intrinsic>%Symbol.unscopables%</emu-intrinsic>).</li><li>If <var>unscopables</var> <emu-xref href=\"/ecmascript-data-types-and-values#sec-object-type\"><a href=\"/ecmascript-data-types-and-values#sec-object-type\">is an Object</a></emu-xref>, then<ol><li>Let <var>blocked</var> be <emu-xref aoid=\"ToBoolean\"><a href=\"/abstract-operations#sec-toboolean\">ToBoolean</a></emu-xref>(? <emu-xref aoid=\"Get\"><a href=\"/abstract-operations#sec-get-o-p\">Get</a></emu-xref>(<var>unscopables</var>, <var>name</var>)).</li><li class=\"exit\">If <var>blocked</var> is <emu-val>true</emu-val>, return <emu-val>false</emu-val>.</li></ol></li><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></emu-alg>\n        ","1.1.2.2":"<p>The CreateMutableBinding concrete method of an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String) and <var>deletable</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It creates in an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>'s associated binding object a property whose name is <var>name</var> and initializes it to the value <emu-val>undefined</emu-val>. If <var>deletable</var> is <emu-val>true</emu-val>, the new property's <var class=\"field\">[[Configurable]]</var> attribute is set to <emu-val>true</emu-val>; otherwise it is set to <emu-val>false</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>bindingObj</var> be <var>envRecord</var>.<var class=\"field\">[[BindingObject]]</var>.</li><li>Perform ? <emu-xref aoid=\"DefinePropertyOrThrow\"><a href=\"/abstract-operations#sec-definepropertyorthrow\">DefinePropertyOrThrow</a></emu-xref>(<var>bindingObj</var>, <var>name</var>, PropertyDescriptor { <var class=\"field\">[[Value]]</var>: <emu-val>undefined</emu-val>, <var class=\"field\">[[Writable]]</var>: <emu-val>true</emu-val>, <var class=\"field\">[[Enumerable]]</var>: <emu-val>true</emu-val>, <var class=\"field\">[[Configurable]]</var>: <var>deletable</var> }).</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p>Normally <var>envRecord</var> will not have a binding for <var>name</var> but if it does, the semantics of <emu-xref aoid=\"DefinePropertyOrThrow\"><a href=\"/abstract-operations#sec-definepropertyorthrow\">DefinePropertyOrThrow</a></emu-xref> may result in an existing binding being replaced or shadowed or cause an <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">abrupt completion</a></emu-xref> to be returned.</p>\n          </div></emu-note>\n        ","1.1.2.3":"<p>The CreateImmutableBinding concrete method of an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> is never used within this specification.</p>\n        ","1.1.2.4":"<p>The InitializeBinding concrete method of an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String) and <var>value</var> (an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref>) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It is used to set the bound value of the current binding of the identifier whose name is <var>name</var> to the value <var>value</var>. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Perform ? <emu-meta effects=\"user-code\"><var>envRecord</var>.SetMutableBinding(<var>name</var>, <var>value</var>, <emu-val>false</emu-val>)</emu-meta>.</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p>In this specification, all uses of CreateMutableBinding for <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Records</a></emu-xref> are immediately followed by a call to InitializeBinding for the same name. Hence, this specification does not explicitly track the initialization state of bindings in <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Records</a></emu-xref>.</p>\n          </div></emu-note>\n        ","1.1.2.5":"<p>The SetMutableBinding concrete method of an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String), <var>value</var> (an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref>), and <var>strict</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It attempts to set the value of the <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>'s associated binding object's property whose name is <var>name</var> to the value <var>value</var>. A property named <var>name</var> normally already exists but if it does not or is not currently writable, error handling is determined by <var>strict</var>. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>bindingObj</var> be <var>envRecord</var>.<var class=\"field\">[[BindingObject]]</var>.</li><li>Let <var>stillExists</var> be ? <emu-xref aoid=\"HasProperty\"><a href=\"/abstract-operations#sec-hasproperty\">HasProperty</a></emu-xref>(<var>bindingObj</var>, <var>name</var>).</li><li class=\"exit\">If <var>stillExists</var> is <emu-val>false</emu-val> and <var>strict</var> is <emu-val>true</emu-val>, throw a <emu-val>ReferenceError</emu-val> exception.</li><li>Perform ? <emu-xref aoid=\"Set\"><a href=\"/abstract-operations#sec-set-o-p-v-throw\">Set</a></emu-xref>(<var>bindingObj</var>, <var>name</var>, <var>value</var>, <var>strict</var>).</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n        ","1.1.2.6":"<p>The GetBindingValue concrete method of an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String) and <var>strict</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It returns the value of its associated binding object's property whose name is <var>name</var>. The property should already exist but if it does not the result depends upon <var>strict</var>. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>bindingObj</var> be <var>envRecord</var>.<var class=\"field\">[[BindingObject]]</var>.</li><li>Let <var>value</var> be ? <emu-xref aoid=\"HasProperty\"><a href=\"/abstract-operations#sec-hasproperty\">HasProperty</a></emu-xref>(<var>bindingObj</var>, <var>name</var>).</li><li>If <var>value</var> is <emu-val>false</emu-val>, then<ol><li class=\"exit\">If <var>strict</var> is <emu-val>false</emu-val>, return <emu-val>undefined</emu-val>.</li><li class=\"exit\">Throw a <emu-val>ReferenceError</emu-val> exception.</li></ol></li><li class=\"exit\">Return ? <emu-xref aoid=\"Get\"><a href=\"/abstract-operations#sec-get-o-p\">Get</a></emu-xref>(<var>bindingObj</var>, <var>name</var>).</li></ol></emu-alg>\n        ","1.1.2.7":"<p>The DeleteBinding concrete method of an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> <var>envRecord</var> takes argument <var>name</var> (a String) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a Boolean or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It can only delete bindings that correspond to properties of the environment object whose <var class=\"field\">[[Configurable]]</var> attribute have the value <emu-val>true</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>bindingObj</var> be <var>envRecord</var>.<var class=\"field\">[[BindingObject]]</var>.</li><li class=\"exit\">Return ? <emu-meta effects=\"user-code\"><var>bindingObj</var>.<var class=\"field\">[[Delete]]</var>(<var>name</var>)</emu-meta>.</li></ol></emu-alg>\n        ","1.1.2.8":"<p>The HasThisBinding concrete method of an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns <emu-val>false</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p><emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Records</a></emu-xref> do not provide a <code>this</code> binding.</p>\n          </div></emu-note>\n        ","1.1.2.9":"<p>The GetThisBinding concrete method of an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> is never used within this specification.</p>\n        ","1.1.2.10":"<p>The HasSuperBinding concrete method of an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns <emu-val>false</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p><emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Records</a></emu-xref> do not provide a <code>super</code> binding.</p>\n          </div></emu-note>\n        ","1.1.2.11":"<p>The WithBaseObject concrete method of an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns an Object or <emu-val>undefined</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">If <var>envRecord</var>.<var class=\"field\">[[IsWithEnvironment]]</var> is <emu-val>true</emu-val>, return <var>envRecord</var>.<var class=\"field\">[[BindingObject]]</var>.</li><li class=\"exit\">Return <emu-val>undefined</emu-val>.</li></ol></emu-alg>\n        ","1.1.3":"<p>A <dfn variants=\"Function Environment Records\">Function Environment Record</dfn> is a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> that is used to represent the top-level scope of a function and, if the function is not an <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-ArrowFunction\">ArrowFunction</a></emu-nt> function or <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-AsyncArrowFunction\">AsyncArrowFunction</a></emu-nt> function, provides a <code>this</code> binding. If a function is not an <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-ArrowFunction\">ArrowFunction</a></emu-nt> function or <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-AsyncArrowFunction\">AsyncArrowFunction</a></emu-nt> function and references <code>super</code>, its Function Environment Record also contains the state that is used to perform <code>super</code> method invocations from within the function.</p>\n        <p>Function Environment Records have the additional state fields listed in <emu-xref href=\"#table-additional-fields-of-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#table-additional-fields-of-function-environment-records\">Table 16</a></emu-xref>.</p>\n        <emu-table id=\"table-additional-fields-of-function-environment-records\" caption=\"Additional Fields of Function Environment Records\" oldids=\"table-16\" data-num=\"16\">\n          <table>\n            <thead>\n              <tr>\n                <th>\n                  Field Name\n                </th>\n                <th>\n                  Value\n                </th>\n                <th>\n                  Meaning\n                </th>\n              </tr>\n            </thead>\n            <tr>\n              <td>\n                <var class=\"field\">[[ThisValue]]</var>\n              </td>\n              <td>\n                an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref>\n              </td>\n              <td>\n                This is the <emu-val>this</emu-val> value used for this invocation of the function.\n              </td>\n            </tr>\n            <tr>\n              <td>\n                <var class=\"field\">[[ThisBindingStatus]]</var>\n              </td>\n              <td>\n                <emu-const>lexical</emu-const>, <emu-const>initialized</emu-const>, or <emu-const>uninitialized</emu-const>\n              </td>\n              <td>\n                If the value is <emu-const>lexical</emu-const>, this is an <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-ArrowFunction\">ArrowFunction</a></emu-nt> or <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-AsyncArrowFunction\">AsyncArrowFunction</a></emu-nt> and does not have a local <emu-val>this</emu-val> value.\n              </td>\n            </tr>\n            <tr>\n              <td>\n                <var class=\"field\">[[FunctionObject]]</var>\n              </td>\n              <td>\n                an ECMAScript <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function object</a></emu-xref>\n              </td>\n              <td>\n                The <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function object</a></emu-xref> whose invocation caused this <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> to be created.\n              </td>\n            </tr>\n            <tr>\n              <td>\n                <var class=\"field\">[[NewTarget]]</var>\n              </td>\n              <td>\n                a <emu-xref href=\"/ecmascript-data-types-and-values#constructor\"><a href=\"/ecmascript-data-types-and-values#constructor\">constructor</a></emu-xref> or <emu-val>undefined</emu-val>\n              </td>\n              <td>\n                If this <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> was created by the <var class=\"field\">[[Construct]]</var> internal method, <var class=\"field\">[[NewTarget]]</var> is the value of the <var class=\"field\">[[Construct]]</var> <var>newTarget</var> parameter. Otherwise, its value is <emu-val>undefined</emu-val>.\n              </td>\n            </tr>\n          </table>\n        </emu-table>\n        <p>Function Environment Records support all of the <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> methods listed in <emu-xref href=\"#table-abstract-methods-of-environment-records\"><a href=\"/executable-code-and-execution-contexts#table-abstract-methods-of-environment-records\">Table 14</a></emu-xref> and share the same specifications for all of those methods except for HasThisBinding, GetThisBinding, and HasSuperBinding.</p>\n\n        ","1.1.3.1":"<p>The abstract operation BindThisValue takes arguments <var>envRecord</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#sec-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-function-environment-records\">Function Environment Record</a></emu-xref>) and <var>value</var> (an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref>) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It sets the <var>envRecord</var>.<var class=\"field\">[[ThisValue]]</var> and records that it has been initialized. It performs the following steps when called:</p>\n          <emu-alg><ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>envRecord</var>.<var class=\"field\">[[ThisBindingStatus]]</var> is not <emu-const>lexical</emu-const>.</li><li class=\"exit\">If <var>envRecord</var>.<var class=\"field\">[[ThisBindingStatus]]</var> is <emu-const>initialized</emu-const>, throw a <emu-val>ReferenceError</emu-val> exception.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[ThisValue]]</var> to <var>value</var>.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[ThisBindingStatus]]</var> to <emu-const>initialized</emu-const>.</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n        ","1.1.3.2":"<p>The HasThisBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-function-environment-records\">Function Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns a Boolean. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">If <var>envRecord</var>.<var class=\"field\">[[ThisBindingStatus]]</var> is <emu-const>lexical</emu-const>, return <emu-val>false</emu-val>.</li><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></emu-alg>\n        ","1.1.3.3":"<p>The GetThisBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-function-environment-records\">Function Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It performs the following steps when called:</p>\n          <emu-alg><ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>envRecord</var>.<var class=\"field\">[[ThisBindingStatus]]</var> is not <emu-const>lexical</emu-const>.</li><li class=\"exit\">If <var>envRecord</var>.<var class=\"field\">[[ThisBindingStatus]]</var> is <emu-const>uninitialized</emu-const>, throw a <emu-val>ReferenceError</emu-val> exception.</li><li class=\"exit\">Return <var>envRecord</var>.<var class=\"field\">[[ThisValue]]</var>.</li></ol></emu-alg>\n        ","1.1.3.4":"<p>The HasSuperBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-function-environment-records\">Function Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns a Boolean. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">If <var>envRecord</var>.<var class=\"field\">[[ThisBindingStatus]]</var> is <emu-const>lexical</emu-const>, return <emu-val>false</emu-val>.</li><li class=\"exit\">If <var>envRecord</var>.<var class=\"field\">[[FunctionObject]]</var>.<var class=\"field\">[[HomeObject]]</var> is <emu-val>undefined</emu-val>, return <emu-val>false</emu-val>.</li><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></emu-alg>\n        ","1.1.3.5":"<p>The abstract operation GetSuperBase takes argument <var>envRecord</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#sec-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-function-environment-records\">Function Environment Record</a></emu-xref>) and returns an Object, <emu-val>null</emu-val>, or <emu-val>undefined</emu-val>. It returns the object that is the base for <code>super</code> property accesses bound in <var>envRecord</var>. The value <emu-val>undefined</emu-val> indicates that such accesses will produce runtime errors. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>home</var> be <var>envRecord</var>.<var class=\"field\">[[FunctionObject]]</var>.<var class=\"field\">[[HomeObject]]</var>.</li><li class=\"exit\">If <var>home</var> is <emu-val>undefined</emu-val>, return <emu-val>undefined</emu-val>.</li><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>home</var> is an <emu-xref href=\"/ecmascript-data-types-and-values#ordinary-object\"><a href=\"/ecmascript-data-types-and-values#ordinary-object\">ordinary object</a></emu-xref>.</li><li class=\"exit\">Return ! <var>home</var>.<var class=\"field\">[[GetPrototypeOf]]</var>().</li></ol></emu-alg>\n        ","1.1.4":"<p>A <dfn variants=\"Global Environment Records\">Global Environment Record</dfn> is used to represent the outer most scope that is shared by all of the ECMAScript <emu-nt><a href=\"/ecmascript-language-scripts-and-modules#prod-Script\">Script</a></emu-nt> elements that are processed in a common <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref>. A Global Environment Record provides the bindings for built-in globals (clause <emu-xref href=\"#sec-global-object\"><a href=\"/global-object#sec-global-object\">19</a></emu-xref>), properties of the <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref>, and for all top-level declarations (<emu-xref href=\"#sec-static-semantics-toplevellexicallyscopeddeclarations\"><a href=\"/syntax-directed-operations#sec-static-semantics-toplevellexicallyscopeddeclarations\">8.2.9</a></emu-xref>, <emu-xref href=\"#sec-static-semantics-toplevelvarscopeddeclarations\"><a href=\"/syntax-directed-operations#sec-static-semantics-toplevelvarscopeddeclarations\">8.2.11</a></emu-xref>) that occur within a <emu-nt><a href=\"/ecmascript-language-scripts-and-modules#prod-Script\">Script</a></emu-nt>.</p>\n        <p>A Global Environment Record is logically a single record but it is specified as a composite encapsulating an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> and a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref>. The <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> has as its base object the <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref> of the associated <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref>. This <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref> is the value returned by the Global Environment Record's GetThisBinding concrete method. The <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> component of a Global Environment Record contains the bindings for all built-in globals (clause <emu-xref href=\"#sec-global-object\"><a href=\"/global-object#sec-global-object\">19</a></emu-xref>) and all bindings introduced by a <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-FunctionDeclaration\">FunctionDeclaration</a></emu-nt>, <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-GeneratorDeclaration\">GeneratorDeclaration</a></emu-nt>, <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-AsyncFunctionDeclaration\">AsyncFunctionDeclaration</a></emu-nt>, <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-AsyncGeneratorDeclaration\">AsyncGeneratorDeclaration</a></emu-nt>, or <emu-nt><a href=\"/ecmascript-language-statements-and-declarations#prod-VariableStatement\">VariableStatement</a></emu-nt> contained in global code. The bindings for all other ECMAScript declarations in global code are contained in the <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> component of the Global Environment Record.</p>\n        <p>Properties may be created directly on a <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref>. Hence, the <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref> component of a Global Environment Record may contain both bindings created explicitly by <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-FunctionDeclaration\">FunctionDeclaration</a></emu-nt>, <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-GeneratorDeclaration\">GeneratorDeclaration</a></emu-nt>, <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-AsyncFunctionDeclaration\">AsyncFunctionDeclaration</a></emu-nt>, <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-AsyncGeneratorDeclaration\">AsyncGeneratorDeclaration</a></emu-nt>, or <emu-nt><a href=\"/ecmascript-language-statements-and-declarations#prod-VariableDeclaration\">VariableDeclaration</a></emu-nt> declarations and bindings created implicitly as properties of the <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref>.</p>\n        <p>Global Environment Records have the additional fields listed in <emu-xref href=\"#table-additional-fields-of-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#table-additional-fields-of-global-environment-records\">Table 17</a></emu-xref>.</p>\n        <emu-table id=\"table-additional-fields-of-global-environment-records\" caption=\"Additional Fields of Global Environment Records\" oldids=\"table-18\" data-num=\"17\">\n          <table>\n            <thead>\n              <tr>\n                <th>\n                  Field Name\n                </th>\n                <th>\n                  Value\n                </th>\n                <th>\n                  Meaning\n                </th>\n              </tr>\n            </thead>\n            <tr>\n              <td>\n                <var class=\"field\">[[ObjectRecord]]</var>\n              </td>\n              <td>\n                an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref>\n              </td>\n              <td>\n                Binding object is the <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref>. It contains global built-in bindings as well as <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-FunctionDeclaration\">FunctionDeclaration</a></emu-nt>, <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-GeneratorDeclaration\">GeneratorDeclaration</a></emu-nt>, <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-AsyncFunctionDeclaration\">AsyncFunctionDeclaration</a></emu-nt>, <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-AsyncGeneratorDeclaration\">AsyncGeneratorDeclaration</a></emu-nt>, and <emu-nt><a href=\"/ecmascript-language-statements-and-declarations#prod-VariableDeclaration\">VariableDeclaration</a></emu-nt> bindings in global code for the associated <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref>.\n              </td>\n            </tr>\n            <tr>\n              <td>\n                <var class=\"field\">[[GlobalThisValue]]</var>\n              </td>\n              <td>\n                an Object\n              </td>\n              <td>\n                The value returned by <code>this</code> in global scope. <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">Hosts</a></emu-xref> may provide any ECMAScript Object value.\n              </td>\n            </tr>\n            <tr>\n              <td>\n                <var class=\"field\">[[DeclarativeRecord]]</var>\n              </td>\n              <td>\n                a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref>\n              </td>\n              <td>\n                <emu-not-ref>Contains</emu-not-ref> bindings for all declarations in global code for the associated <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref> code except for <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-FunctionDeclaration\">FunctionDeclaration</a></emu-nt>, <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-GeneratorDeclaration\">GeneratorDeclaration</a></emu-nt>, <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-AsyncFunctionDeclaration\">AsyncFunctionDeclaration</a></emu-nt>, <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-AsyncGeneratorDeclaration\">AsyncGeneratorDeclaration</a></emu-nt>, and <emu-nt><a href=\"/ecmascript-language-statements-and-declarations#prod-VariableDeclaration\">VariableDeclaration</a></emu-nt> bindings.\n              </td>\n            </tr>\n          </table>\n        </emu-table>\n\n        ","1.1.4.1":"<p>The HasBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref> <var>envRecord</var> takes argument <var>name</var> (a String) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a Boolean or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It determines if the argument identifier is one of the identifiers bound by the record. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>declRecord</var> be <var>envRecord</var>.<var class=\"field\">[[DeclarativeRecord]]</var>.</li><li class=\"exit\">If ! <var>declRecord</var>.HasBinding(<var>name</var>) is <emu-val>true</emu-val>, return <emu-val>true</emu-val>.</li><li>Let <var>objRecord</var> be <var>envRecord</var>.<var class=\"field\">[[ObjectRecord]]</var>.</li><li class=\"exit\">Return ? <emu-meta effects=\"user-code\"><var>objRecord</var>.HasBinding(<var>name</var>)</emu-meta>.</li></ol></emu-alg>\n        ","1.1.4.2":"<p>The CreateMutableBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String) and <var>deletable</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It creates a new mutable binding for the name <var>name</var> that is uninitialized. The binding is created in the associated DeclarativeRecord. A binding for <var>name</var> must not already exist in the DeclarativeRecord. If <var>deletable</var> is <emu-val>true</emu-val>, the new binding is marked as being subject to deletion. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>declRecord</var> be <var>envRecord</var>.<var class=\"field\">[[DeclarativeRecord]]</var>.</li><li class=\"exit\">If ! <var>declRecord</var>.HasBinding(<var>name</var>) is <emu-val>true</emu-val>, throw a <emu-val>TypeError</emu-val> exception.</li><li class=\"exit\">Return ! <var>declRecord</var>.CreateMutableBinding(<var>name</var>, <var>deletable</var>).</li></ol></emu-alg>\n        ","1.1.4.3":"<p>The CreateImmutableBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String) and <var>strict</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It creates a new immutable binding for the name <var>name</var> that is uninitialized. A binding must not already exist in this <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> for <var>name</var>. If <var>strict</var> is <emu-val>true</emu-val>, the new binding is marked as a strict binding. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>declRecord</var> be <var>envRecord</var>.<var class=\"field\">[[DeclarativeRecord]]</var>.</li><li class=\"exit\">If ! <var>declRecord</var>.HasBinding(<var>name</var>) is <emu-val>true</emu-val>, throw a <emu-val>TypeError</emu-val> exception.</li><li class=\"exit\">Return ! <var>declRecord</var>.CreateImmutableBinding(<var>name</var>, <var>strict</var>).</li></ol></emu-alg>\n        ","1.1.4.4":"<p>The InitializeBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String) and <var>value</var> (an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref>) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It is used to set the bound value of the current binding of the identifier whose name is <var>name</var> to the value <var>value</var>. An uninitialized binding for <var>name</var> must already exist. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>declRecord</var> be <var>envRecord</var>.<var class=\"field\">[[DeclarativeRecord]]</var>.</li><li>If ! <var>declRecord</var>.HasBinding(<var>name</var>) is <emu-val>true</emu-val>, then<ol><li class=\"exit\">Return ! <var>declRecord</var>.InitializeBinding(<var>name</var>, <var>value</var>).</li></ol></li><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: If the binding exists, it must be in the <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref>.</li><li>Let <var>objRecord</var> be <var>envRecord</var>.<var class=\"field\">[[ObjectRecord]]</var>.</li><li class=\"exit\">Return ? <emu-meta effects=\"user-code\"><var>objRecord</var>.InitializeBinding(<var>name</var>, <var>value</var>)</emu-meta>.</li></ol></emu-alg>\n        ","1.1.4.5":"<p>The SetMutableBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String), <var>value</var> (an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref>), and <var>strict</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It attempts to change the bound value of the current binding of the identifier whose name is <var>name</var> to the value <var>value</var>. If the binding is an immutable binding and <var>strict</var> is <emu-val>true</emu-val>, a <emu-val>TypeError</emu-val> is thrown. A binding named <var>name</var> normally already exists but if it does not or is not currently writable, error handling is determined by <var>strict</var>. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>declRecord</var> be <var>envRecord</var>.<var class=\"field\">[[DeclarativeRecord]]</var>.</li><li>If ! <var>declRecord</var>.HasBinding(<var>name</var>) is <emu-val>true</emu-val>, then<ol><li class=\"exit\">Return ? <var>declRecord</var>.SetMutableBinding(<var>name</var>, <var>value</var>, <var>strict</var>).</li></ol></li><li>Let <var>objRecord</var> be <var>envRecord</var>.<var class=\"field\">[[ObjectRecord]]</var>.</li><li class=\"exit\">Return ? <emu-meta effects=\"user-code\"><var>objRecord</var>.SetMutableBinding(<var>name</var>, <var>value</var>, <var>strict</var>)</emu-meta>.</li></ol></emu-alg>\n        ","1.1.4.6":"<p>The GetBindingValue concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String) and <var>strict</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It returns the value of its bound identifier whose name is <var>name</var>. If the binding is an uninitialized binding, it will throw a <emu-val>ReferenceError</emu-val> exception. A binding named <var>name</var> normally already exists but if it does not or is not currently writable, error handling is determined by <var>strict</var>. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>declRecord</var> be <var>envRecord</var>.<var class=\"field\">[[DeclarativeRecord]]</var>.</li><li>If ! <var>declRecord</var>.HasBinding(<var>name</var>) is <emu-val>true</emu-val>, then<ol><li class=\"exit\">Return ? <var>declRecord</var>.GetBindingValue(<var>name</var>, <var>strict</var>).</li></ol></li><li>Let <var>objRecord</var> be <var>envRecord</var>.<var class=\"field\">[[ObjectRecord]]</var>.</li><li class=\"exit\">Return ? <emu-meta effects=\"user-code\"><var>objRecord</var>.GetBindingValue(<var>name</var>, <var>strict</var>)</emu-meta>.</li></ol></emu-alg>\n        ","1.1.4.7":"<p>The DeleteBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref> <var>envRecord</var> takes argument <var>name</var> (a String) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a Boolean or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It can only delete bindings that have been explicitly designated as being subject to deletion. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>declRecord</var> be <var>envRecord</var>.<var class=\"field\">[[DeclarativeRecord]]</var>.</li><li>If ! <var>declRecord</var>.HasBinding(<var>name</var>) is <emu-val>true</emu-val>, then<ol><li class=\"exit\">Return ! <var>declRecord</var>.DeleteBinding(<var>name</var>).</li></ol></li><li>Let <var>objRecord</var> be <var>envRecord</var>.<var class=\"field\">[[ObjectRecord]]</var>.</li><li>Let <var>globalObj</var> be <var>objRecord</var>.<var class=\"field\">[[BindingObject]]</var>.</li><li>Let <var>existingProperty</var> be ? <emu-xref aoid=\"HasOwnProperty\"><a href=\"/abstract-operations#sec-hasownproperty\">HasOwnProperty</a></emu-xref>(<var>globalObj</var>, <var>name</var>).</li><li>If <var>existingProperty</var> is <emu-val>true</emu-val>, then<ol><li class=\"exit\">Return ? <emu-meta effects=\"user-code\"><var>objRecord</var>.DeleteBinding(<var>name</var>)</emu-meta>.</li></ol></li><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></emu-alg>\n        ","1.1.4.8":"<p>The HasThisBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns <emu-val>true</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p><emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Records</a></emu-xref> always provide a <code>this</code> binding.</p>\n          </div></emu-note>\n        ","1.1.4.9":"<p>The GetThisBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> an Object. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">Return <var>envRecord</var>.<var class=\"field\">[[GlobalThisValue]]</var>.</li></ol></emu-alg>\n        ","1.1.4.10":"<p>The HasSuperBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns <emu-val>false</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p><emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Records</a></emu-xref> do not provide a <code>super</code> binding.</p>\n          </div></emu-note>\n        ","1.1.4.11":"<p>The WithBaseObject concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns <emu-val>undefined</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">Return <emu-val>undefined</emu-val>.</li></ol></emu-alg>\n        ","1.1.4.12":"<p>The abstract operation HasLexicalDeclaration takes arguments <var>envRecord</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref>) and <var>name</var> (a String) and returns a Boolean. It determines if the argument identifier has a binding in <var>envRecord</var> that was created using a lexical declaration such as a <emu-nt><a href=\"/ecmascript-language-statements-and-declarations#prod-LexicalDeclaration\">LexicalDeclaration</a></emu-nt> or a <emu-nt><a href=\"/ecmascript-language-functions-and-classes#prod-ClassDeclaration\">ClassDeclaration</a></emu-nt>. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>declRecord</var> be <var>envRecord</var>.<var class=\"field\">[[DeclarativeRecord]]</var>.</li><li class=\"exit\">Return ! <var>declRecord</var>.HasBinding(<var>name</var>).</li></ol></emu-alg>\n        ","1.1.4.13":"<p>The abstract operation HasRestrictedGlobalProperty takes arguments <var>envRecord</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref>) and <var>name</var> (a String) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a Boolean or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It determines if the argument identifier is the name of a property of the <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref> that must not be shadowed by a global lexical binding. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>objRecord</var> be <var>envRecord</var>.<var class=\"field\">[[ObjectRecord]]</var>.</li><li>Let <var>globalObj</var> be <var>objRecord</var>.<var class=\"field\">[[BindingObject]]</var>.</li><li>Let <var>existingProperty</var> be ? <emu-meta effects=\"user-code\"><var>globalObj</var>.<var class=\"field\">[[GetOwnProperty]]</var>(<var>name</var>)</emu-meta>.</li><li class=\"exit\">If <var>existingProperty</var> is <emu-val>undefined</emu-val>, return <emu-val>false</emu-val>.</li><li class=\"exit\">If <var>existingProperty</var>.<var class=\"field\">[[Configurable]]</var> is <emu-val>true</emu-val>, return <emu-val>false</emu-val>.</li><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p>Properties may exist upon a <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref> that were directly created rather than being declared using a var or function declaration. A global lexical binding may not be created that has the same name as a non-configurable property of the <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref>. The global property <emu-val>\"undefined\"</emu-val> is an example of such a property.</p>\n          </div></emu-note>\n        ","1.1.4.14":"<p>The abstract operation CanDeclareGlobalVar takes arguments <var>envRecord</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref>) and <var>name</var> (a String) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a Boolean or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It determines if a corresponding <emu-xref aoid=\"CreateGlobalVarBinding\"><a href=\"/executable-code-and-execution-contexts#sec-createglobalvarbinding\">CreateGlobalVarBinding</a></emu-xref> call would succeed if called for the same argument <var>name</var>. Redundant var declarations and var declarations for pre-existing <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref> properties are allowed. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>objRecord</var> be <var>envRecord</var>.<var class=\"field\">[[ObjectRecord]]</var>.</li><li>Let <var>globalObj</var> be <var>objRecord</var>.<var class=\"field\">[[BindingObject]]</var>.</li><li>Let <var>hasProperty</var> be ? <emu-xref aoid=\"HasOwnProperty\"><a href=\"/abstract-operations#sec-hasownproperty\">HasOwnProperty</a></emu-xref>(<var>globalObj</var>, <var>name</var>).</li><li class=\"exit\">If <var>hasProperty</var> is <emu-val>true</emu-val>, return <emu-val>true</emu-val>.</li><li class=\"exit\">Return ? <emu-xref aoid=\"IsExtensible\"><a href=\"/abstract-operations#sec-isextensible-o\">IsExtensible</a></emu-xref>(<var>globalObj</var>).</li></ol></emu-alg>\n        ","1.1.4.15":"<p>The abstract operation CanDeclareGlobalFunction takes arguments <var>envRecord</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref>) and <var>name</var> (a String) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a Boolean or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It determines if a corresponding <emu-xref aoid=\"CreateGlobalFunctionBinding\"><a href=\"/executable-code-and-execution-contexts#sec-createglobalfunctionbinding\">CreateGlobalFunctionBinding</a></emu-xref> call would succeed if called for the same argument <var>name</var>. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>objRecord</var> be <var>envRecord</var>.<var class=\"field\">[[ObjectRecord]]</var>.</li><li>Let <var>globalObj</var> be <var>objRecord</var>.<var class=\"field\">[[BindingObject]]</var>.</li><li>Let <var>existingProperty</var> be ? <emu-meta effects=\"user-code\"><var>globalObj</var>.<var class=\"field\">[[GetOwnProperty]]</var>(<var>name</var>)</emu-meta>.</li><li class=\"exit\">If <var>existingProperty</var> is <emu-val>undefined</emu-val>, return ? <emu-xref aoid=\"IsExtensible\"><a href=\"/abstract-operations#sec-isextensible-o\">IsExtensible</a></emu-xref>(<var>globalObj</var>).</li><li class=\"exit\">If <var>existingProperty</var>.<var class=\"field\">[[Configurable]]</var> is <emu-val>true</emu-val>, return <emu-val>true</emu-val>.</li><li class=\"exit\">If <emu-xref aoid=\"IsDataDescriptor\"><a href=\"/ecmascript-data-types-and-values#sec-isdatadescriptor\">IsDataDescriptor</a></emu-xref>(<var>existingProperty</var>) is <emu-val>true</emu-val> and <var>existingProperty</var> has attribute values { <var class=\"field\">[[Writable]]</var>: <emu-val>true</emu-val>, <var class=\"field\">[[Enumerable]]</var>: <emu-val>true</emu-val> }, return <emu-val>true</emu-val>.</li><li class=\"exit\">Return <emu-val>false</emu-val>.</li></ol></emu-alg>\n        ","1.1.4.16":"<p>The abstract operation CreateGlobalVarBinding takes arguments <var>envRecord</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref>), <var>name</var> (a String), and <var>deletable</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It creates and initializes a mutable binding in the associated <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref>. If a binding already exists, it is reused and assumed to be initialized. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>objRecord</var> be <var>envRecord</var>.<var class=\"field\">[[ObjectRecord]]</var>.</li><li>Let <var>globalObj</var> be <var>objRecord</var>.<var class=\"field\">[[BindingObject]]</var>.</li><li>Let <var>hasProperty</var> be ? <emu-xref aoid=\"HasOwnProperty\"><a href=\"/abstract-operations#sec-hasownproperty\">HasOwnProperty</a></emu-xref>(<var>globalObj</var>, <var>name</var>).</li><li>Let <var>extensible</var> be ? <emu-xref aoid=\"IsExtensible\"><a href=\"/abstract-operations#sec-isextensible-o\">IsExtensible</a></emu-xref>(<var>globalObj</var>).</li><li>If <var>hasProperty</var> is <emu-val>false</emu-val> and <var>extensible</var> is <emu-val>true</emu-val>, then<ol><li>Perform ? <emu-meta effects=\"user-code\"><var>objRecord</var>.CreateMutableBinding(<var>name</var>, <var>deletable</var>)</emu-meta>.</li><li>Perform ? <emu-meta effects=\"user-code\"><var>objRecord</var>.InitializeBinding(<var>name</var>, <emu-val>undefined</emu-val>)</emu-meta>.</li></ol></li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n        ","1.1.4.17":"<p>The abstract operation CreateGlobalFunctionBinding takes arguments <var>envRecord</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref>), <var>name</var> (a String), <var>value</var> (an ECMAScript <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function object</a></emu-xref>), and <var>deletable</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It creates and initializes a mutable binding in the associated <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref>. If a binding already exists, it is replaced. It performs the following steps when called:</p>\n          <emu-alg><ol><li>Let <var>objRecord</var> be <var>envRecord</var>.<var class=\"field\">[[ObjectRecord]]</var>.</li><li>Let <var>globalObj</var> be <var>objRecord</var>.<var class=\"field\">[[BindingObject]]</var>.</li><li>Let <var>existingProperty</var> be ? <emu-meta effects=\"user-code\"><var>globalObj</var>.<var class=\"field\">[[GetOwnProperty]]</var>(<var>name</var>)</emu-meta>.</li><li>If <var>existingProperty</var> is <emu-val>undefined</emu-val> or <var>existingProperty</var>.<var class=\"field\">[[Configurable]]</var> is <emu-val>true</emu-val>, then<ol><li>Let <var>propertyDesc</var> be the PropertyDescriptor { <var class=\"field\">[[Value]]</var>: <var>value</var>, <var class=\"field\">[[Writable]]</var>: <emu-val>true</emu-val>, <var class=\"field\">[[Enumerable]]</var>: <emu-val>true</emu-val>, <var class=\"field\">[[Configurable]]</var>: <var>deletable</var> }.</li></ol></li><li>Else,<ol><li>Let <var>propertyDesc</var> be the PropertyDescriptor { <var class=\"field\">[[Value]]</var>: <var>value</var> }.</li></ol></li><li>Perform ? <emu-xref aoid=\"DefinePropertyOrThrow\"><a href=\"/abstract-operations#sec-definepropertyorthrow\">DefinePropertyOrThrow</a></emu-xref>(<var>globalObj</var>, <var>name</var>, <var>propertyDesc</var>).</li><li id=\"step-createglobalfunctionbinding-set\">Perform ? <emu-xref aoid=\"Set\"><a href=\"/abstract-operations#sec-set-o-p-v-throw\">Set</a></emu-xref>(<var>globalObj</var>, <var>name</var>, <var>value</var>, <emu-val>false</emu-val>).</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p>Global function declarations are always represented as own properties of the <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref>. If possible, an existing own property is reconfigured to have a standard set of attribute values. Step <emu-xref href=\"#step-createglobalfunctionbinding-set\"><a href=\"/executable-code-and-execution-contexts#step-createglobalfunctionbinding-set\">7</a></emu-xref> is equivalent to what calling the InitializeBinding concrete method would do and if <var>globalObj</var> is a Proxy will produce the same sequence of Proxy trap calls.</p>\n          </div></emu-note>\n        ","1.1.5":"<p>A <dfn variants=\"Module Environment Records\">Module Environment Record</dfn> is a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> that is used to represent the outer scope of an ECMAScript <emu-nt><a href=\"/ecmascript-language-scripts-and-modules#prod-Module\">Module</a></emu-nt>. In additional to normal mutable and immutable bindings, Module Environment Records also provide immutable import bindings which are bindings that provide indirect access to a target binding that exists in another <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>.</p>\n        <p>Module Environment Records support all of the <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> methods listed in <emu-xref href=\"#table-abstract-methods-of-environment-records\"><a href=\"/executable-code-and-execution-contexts#table-abstract-methods-of-environment-records\">Table 14</a></emu-xref> and share the same specifications for all of those methods except for GetBindingValue, DeleteBinding, HasThisBinding, and GetThisBinding.</p>\n\n        ","1.1.5.1":"<p>The GetBindingValue concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Record</a></emu-xref> <var>envRecord</var> takes arguments <var>name</var> (a String) and <var>strict</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It returns the value of its bound identifier whose name is <var>name</var>. However, if the binding is an indirect binding the value of the target binding is returned. If the binding exists but is uninitialized a <emu-val>ReferenceError</emu-val> is thrown. It performs the following steps when called:</p>\n          <emu-alg><ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>strict</var> is <emu-val>true</emu-val>.</li><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>envRecord</var> has a binding for <var>name</var>.</li><li>If the binding for <var>name</var> is an indirect binding, then<ol><li>Let <var>module</var> and <var>targetName</var> be the indirection values provided when this binding for <var>name</var> was created.</li><li>Let <var>targetEnv</var> be <var>module</var>.<var class=\"field\">[[Environment]]</var>.</li><li class=\"exit\">If <var>targetEnv</var> is <emu-const>empty</emu-const>, throw a <emu-val>ReferenceError</emu-val> exception.</li><li class=\"exit\">Return ? <emu-meta effects=\"user-code\"><var>targetEnv</var>.GetBindingValue(<var>targetName</var>, <emu-val>true</emu-val>)</emu-meta>.</li></ol></li><li class=\"exit\">If the binding for <var>name</var> in <var>envRecord</var> is an uninitialized binding, throw a <emu-val>ReferenceError</emu-val> exception.</li><li class=\"exit\">Return the value currently bound to <var>name</var> in <var>envRecord</var>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p><var>strict</var> will always be <emu-val>true</emu-val> because a <emu-nt><a href=\"/ecmascript-language-scripts-and-modules#prod-Module\">Module</a></emu-nt> is always <emu-xref href=\"/ecmascript-language-source-code#sec-strict-mode-code\"><a href=\"/ecmascript-language-source-code#sec-strict-mode-code\">strict mode code</a></emu-xref>.</p>\n          </div></emu-note>\n        ","1.1.5.2":"<p>The DeleteBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Record</a></emu-xref> is never used within this specification.</p>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p><emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Records</a></emu-xref> are only used within strict code and an <emu-xref href=\"/error-handling-and-language-extensions#early-error\"><a href=\"/error-handling-and-language-extensions#early-error\">early error</a></emu-xref> rule prevents the delete operator, in strict code, from being applied to a <emu-xref href=\"/ecmascript-data-types-and-values#sec-reference-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-reference-record-specification-type\">Reference Record</a></emu-xref> that would resolve to a <emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Record</a></emu-xref> binding. See <emu-xref href=\"#sec-delete-operator-static-semantics-early-errors\"><a href=\"/ecmascript-language-expressions#sec-delete-operator-static-semantics-early-errors\">13.5.1.1</a></emu-xref>.</p>\n          </div></emu-note>\n        ","1.1.5.3":"<p>The HasThisBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns <emu-val>true</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">Return <emu-val>true</emu-val>.</li></ol></emu-alg>\n          <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n            <p><emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Records</a></emu-xref> always provide a <code>this</code> binding.</p>\n          </div></emu-note>\n        ","1.1.5.4":"<p>The GetThisBinding concrete method of a <emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Record</a></emu-xref> <var>envRecord</var> takes no arguments and returns a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-val>undefined</emu-val>. It performs the following steps when called:</p>\n          <emu-alg><ol><li class=\"exit\">Return <emu-val>undefined</emu-val>.</li></ol></emu-alg>\n        ","1.1.5.5":"<p>The abstract operation CreateImportBinding takes arguments <var>envRecord</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Record</a></emu-xref>), <var>name</var> (a String), <var>targetModule</var> (a <emu-xref href=\"/ecmascript-language-scripts-and-modules#sec-abstract-module-records\"><a href=\"/ecmascript-language-scripts-and-modules#sec-abstract-module-records\">Module Record</a></emu-xref>), and <var>targetName</var> (a String) and returns <emu-const>unused</emu-const>. It creates a new initialized immutable indirect binding for the name <var>name</var>. A binding must not already exist in <var>envRecord</var> for <var>name</var>. <var>targetName</var> is the name of a binding that exists in <var>targetModule</var>'s <emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Record</a></emu-xref>. Accesses to the value of the new binding will indirectly access the bound value of the target binding. It performs the following steps when called:</p>\n          <emu-alg><ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>envRecord</var> does not already have a binding for <var>name</var>.</li><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: When <var>targetModule</var>.<var class=\"field\">[[Environment]]</var> is instantiated, it will have a direct binding for <var>targetName</var>.</li><li>Create an immutable indirect binding in <var>envRecord</var> for <var>name</var> that references <var>targetModule</var> and <var>targetName</var> as its target binding and record that the binding is initialized.</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n        ","1.2":"<p>The following <emu-xref href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\"><a href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\">abstract operations</a></emu-xref> are used in this specification to operate upon <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Records</a></emu-xref>:</p>\n\n      ","1.2.1":"<p>The abstract operation GetIdentifierReference takes arguments <var>envRecord</var> (an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> or <emu-val>null</emu-val>), <var>name</var> (a String), and <var>strict</var> (a Boolean) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a <emu-xref href=\"/ecmascript-data-types-and-values#sec-reference-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-reference-record-specification-type\">Reference Record</a></emu-xref> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It performs the following steps when called:</p>\n        <emu-alg><ol><li>If <var>envRecord</var> is <emu-val>null</emu-val>, then<ol><li class=\"exit\">Return the <emu-xref href=\"/ecmascript-data-types-and-values#sec-reference-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-reference-record-specification-type\">Reference Record</a></emu-xref> { <var class=\"field\">[[Base]]</var>: <emu-const>unresolvable</emu-const>, <var class=\"field\">[[ReferencedName]]</var>: <var>name</var>, <var class=\"field\">[[Strict]]</var>: <var>strict</var>, <var class=\"field\">[[ThisValue]]</var>: <emu-const>empty</emu-const> }.</li></ol></li><li>Let <var>exists</var> be ? <emu-meta effects=\"user-code\"><var>envRecord</var>.HasBinding(<var>name</var>)</emu-meta>.</li><li>If <var>exists</var> is <emu-val>true</emu-val>, then<ol><li class=\"exit\">Return the <emu-xref href=\"/ecmascript-data-types-and-values#sec-reference-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-reference-record-specification-type\">Reference Record</a></emu-xref> { <var class=\"field\">[[Base]]</var>: <var>envRecord</var>, <var class=\"field\">[[ReferencedName]]</var>: <var>name</var>, <var class=\"field\">[[Strict]]</var>: <var>strict</var>, <var class=\"field\">[[ThisValue]]</var>: <emu-const>empty</emu-const> }.</li></ol></li><li>Let <var>outer</var> be <var>envRecord</var>.<var class=\"field\">[[OuterEnv]]</var>.</li><li class=\"exit\">Return ? GetIdentifierReference(<var>outer</var>, <var>name</var>, <var>strict</var>).</li></ol></emu-alg>\n      ","1.2.2":"<p>The abstract operation NewDeclarativeEnvironment takes argument <var>outerEnv</var> (an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> or <emu-val>null</emu-val>) and returns a <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref>. It performs the following steps when called:</p>\n        <emu-alg><ol><li>Let <var>envRecord</var> be a new <emu-xref href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-declarative-environment-records\">Declarative Environment Record</a></emu-xref> containing no bindings.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[OuterEnv]]</var> to <var>outerEnv</var>.</li><li class=\"exit\">Return <var>envRecord</var>.</li></ol></emu-alg>\n      ","1.2.3":"<p>The abstract operation NewObjectEnvironment takes arguments <var>obj</var> (an Object), <var>isWithEnv</var> (a Boolean), and <var>outerEnv</var> (an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> or <emu-val>null</emu-val>) and returns an <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref>. It performs the following steps when called:</p>\n        <emu-alg><ol><li>Let <var>envRecord</var> be a new <emu-xref href=\"/executable-code-and-execution-contexts#sec-object-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-object-environment-records\">Object Environment Record</a></emu-xref>.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[BindingObject]]</var> to <var>obj</var>.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[IsWithEnvironment]]</var> to <var>isWithEnv</var>.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[OuterEnv]]</var> to <var>outerEnv</var>.</li><li class=\"exit\">Return <var>envRecord</var>.</li></ol></emu-alg>\n      ","1.2.4":"<p>The abstract operation NewFunctionEnvironment takes arguments <var>func</var> (an ECMAScript <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function object</a></emu-xref>) and <var>newTarget</var> (an Object or <emu-val>undefined</emu-val>) and returns a <emu-xref href=\"/executable-code-and-execution-contexts#sec-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-function-environment-records\">Function Environment Record</a></emu-xref>. It performs the following steps when called:</p>\n        <emu-alg><ol><li>Let <var>envRecord</var> be a new <emu-xref href=\"/executable-code-and-execution-contexts#sec-function-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-function-environment-records\">Function Environment Record</a></emu-xref> containing no bindings.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[FunctionObject]]</var> to <var>func</var>.</li><li>If <var>func</var>.<var class=\"field\">[[ThisMode]]</var> is <emu-const>lexical</emu-const>, set <var>envRecord</var>.<var class=\"field\">[[ThisBindingStatus]]</var> to <emu-const>lexical</emu-const>.</li><li>Else, set <var>envRecord</var>.<var class=\"field\">[[ThisBindingStatus]]</var> to <emu-const>uninitialized</emu-const>.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[NewTarget]]</var> to <var>newTarget</var>.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[OuterEnv]]</var> to <var>func</var>.<var class=\"field\">[[Environment]]</var>.</li><li class=\"exit\">Return <var>envRecord</var>.</li></ol></emu-alg>\n      ","1.2.5":"<p>The abstract operation NewGlobalEnvironment takes arguments <var>obj</var> (an Object) and <var>thisValue</var> (an Object) and returns a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref>. It performs the following steps when called:</p>\n        <emu-alg><ol><li>Let <var>objRecord</var> be <emu-xref aoid=\"NewObjectEnvironment\"><a href=\"/executable-code-and-execution-contexts#sec-newobjectenvironment\">NewObjectEnvironment</a></emu-xref>(<var>obj</var>, <emu-val>false</emu-val>, <emu-val>null</emu-val>).</li><li>Let <var>declRecord</var> be <emu-xref aoid=\"NewDeclarativeEnvironment\"><a href=\"/executable-code-and-execution-contexts#sec-newdeclarativeenvironment\">NewDeclarativeEnvironment</a></emu-xref>(<emu-val>null</emu-val>).</li><li>Let <var>envRecord</var> be a new <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref>.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[ObjectRecord]]</var> to <var>objRecord</var>.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[GlobalThisValue]]</var> to <var>thisValue</var>.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[DeclarativeRecord]]</var> to <var>declRecord</var>.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[OuterEnv]]</var> to <emu-val>null</emu-val>.</li><li class=\"exit\">Return <var>envRecord</var>.</li></ol></emu-alg>\n      ","1.2.6":"<p>The abstract operation NewModuleEnvironment takes argument <var>outerEnv</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#sec-global-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-global-environment-records\">Global Environment Record</a></emu-xref>) and returns a <emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Record</a></emu-xref>. It performs the following steps when called:</p>\n        <emu-alg><ol><li>Let <var>envRecord</var> be a new <emu-xref href=\"/executable-code-and-execution-contexts#sec-module-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-module-environment-records\">Module Environment Record</a></emu-xref> containing no bindings.</li><li>Set <var>envRecord</var>.<var class=\"field\">[[OuterEnv]]</var> to <var>outerEnv</var>.</li><li class=\"exit\">Return <var>envRecord</var>.</li></ol></emu-alg>\n      ","2.1":"<p>The following <emu-xref href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\"><a href=\"/notational-conventions#sec-algorithm-conventions-abstract-operations\">abstract operations</a></emu-xref> are used in this specification to operate upon <emu-xref href=\"/executable-code-and-execution-contexts#privateenvironment-record\"><a href=\"/executable-code-and-execution-contexts#privateenvironment-record\">PrivateEnvironment Records</a></emu-xref>:</p>\n\n      ","2.1.1":"<p>The abstract operation NewPrivateEnvironment takes argument <var>outerPrivateEnv</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#privateenvironment-record\"><a href=\"/executable-code-and-execution-contexts#privateenvironment-record\">PrivateEnvironment Record</a></emu-xref> or <emu-val>null</emu-val>) and returns a <emu-xref href=\"/executable-code-and-execution-contexts#privateenvironment-record\"><a href=\"/executable-code-and-execution-contexts#privateenvironment-record\">PrivateEnvironment Record</a></emu-xref>. It performs the following steps when called:</p>\n        <emu-alg><ol><li>Let <var>names</var> be a new empty <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref>.</li><li class=\"exit\">Return the <emu-xref href=\"/executable-code-and-execution-contexts#privateenvironment-record\"><a href=\"/executable-code-and-execution-contexts#privateenvironment-record\">PrivateEnvironment Record</a></emu-xref> { <var class=\"field\">[[OuterPrivateEnvironment]]</var>: <var>outerPrivateEnv</var>, <var class=\"field\">[[Names]]</var>: <var>names</var> }.</li></ol></emu-alg>\n      ","2.1.2":"<p>The abstract operation ResolvePrivateIdentifier takes arguments <var>privateEnv</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#privateenvironment-record\"><a href=\"/executable-code-and-execution-contexts#privateenvironment-record\">PrivateEnvironment Record</a></emu-xref>) and <var>identifier</var> (a String) and returns a <emu-xref href=\"/ecmascript-data-types-and-values#sec-private-names\"><a href=\"/ecmascript-data-types-and-values#sec-private-names\">Private Name</a></emu-xref>. It performs the following steps when called:</p>\n        <emu-alg><ol><li>Let <var>names</var> be <var>privateEnv</var>.<var class=\"field\">[[Names]]</var>.</li><li>For each <emu-xref href=\"/ecmascript-data-types-and-values#sec-private-names\"><a href=\"/ecmascript-data-types-and-values#sec-private-names\">Private Name</a></emu-xref> <var>privateName</var> of <var>names</var>, do<ol><li>If <var>privateName</var>.<var class=\"field\">[[Description]]</var> is <var>identifier</var>, then<ol><li class=\"exit\">Return <var>privateName</var>.</li></ol></li></ol></li><li>Let <var>outerPrivateEnv</var> be <var>privateEnv</var>.<var class=\"field\">[[OuterPrivateEnvironment]]</var>.</li><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>outerPrivateEnv</var> is not <emu-val>null</emu-val>.</li><li class=\"exit\">Return ResolvePrivateIdentifier(<var>outerPrivateEnv</var>, <var>identifier</var>).</li></ol></emu-alg>\n      ","3.1":"<p>The abstract operation InitializeHostDefinedRealm takes no arguments and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>realm</var> be a new <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref>.</li><li>Perform <emu-xref aoid=\"CreateIntrinsics\"><a href=\"/executable-code-and-execution-contexts#sec-createintrinsics\">CreateIntrinsics</a></emu-xref>(<var>realm</var>).</li><li>Set <var>realm</var>.<var class=\"field\">[[AgentSignifier]]</var> to <emu-xref aoid=\"AgentSignifier\"><a href=\"/executable-code-and-execution-contexts#sec-agentsignifier\">AgentSignifier</a></emu-xref>().</li><li>Set <var>realm</var>.<var class=\"field\">[[TemplateMap]]</var> to a new empty <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref>.</li><li>Let <var>newContext</var> be a new <emu-xref href=\"/executable-code-and-execution-contexts#sec-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#sec-execution-contexts\">execution context</a></emu-xref>.</li><li>Set the Function of <var>newContext</var> to <emu-val>null</emu-val>.</li><li>Set the <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">Realm</a></emu-xref> of <var>newContext</var> to <var>realm</var>.</li><li>Set the ScriptOrModule of <var>newContext</var> to <emu-val>null</emu-val>.</li><li>Push <var>newContext</var> onto the <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref>; <var>newContext</var> is now the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>.</li><li>If the <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref> requires use of a specific object to serve as <var>realm</var>'s <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref>, then<ol><li>Let <var>global</var> be such an object created in a <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> manner.</li></ol></li><li>Else,<ol><li>Let <var>global</var> be <emu-xref aoid=\"OrdinaryObjectCreate\"><a href=\"/ordinary-and-exotic-objects-behaviours#sec-ordinaryobjectcreate\">OrdinaryObjectCreate</a></emu-xref>(<var>realm</var>.<var class=\"field\">[[Intrinsics]]</var>.[[<emu-intrinsic>%Object.prototype%</emu-intrinsic>]]).</li></ol></li><li>If the <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref> requires that the <code>this</code> binding in <var>realm</var>'s global scope return an object other than the <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref>, then<ol><li>Let <var>thisValue</var> be such an object created in a <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> manner.</li></ol></li><li>Else,<ol><li>Let <var>thisValue</var> be <var>global</var>.</li></ol></li><li>Set <var>realm</var>.<var class=\"field\">[[GlobalObject]]</var> to <var>global</var>.</li><li>Set <var>realm</var>.<var class=\"field\">[[GlobalEnv]]</var> to <emu-xref aoid=\"NewGlobalEnvironment\"><a href=\"/executable-code-and-execution-contexts#sec-newglobalenvironment\">NewGlobalEnvironment</a></emu-xref>(<var>global</var>, <var>thisValue</var>).</li><li>Perform ? <emu-xref aoid=\"SetDefaultGlobalBindings\"><a href=\"/executable-code-and-execution-contexts#sec-setdefaultglobalbindings\">SetDefaultGlobalBindings</a></emu-xref>(<var>realm</var>).</li><li>Create any <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref> properties on <var>global</var>.</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n    ","3.2":"<p>The abstract operation CreateIntrinsics takes argument <var>realmRecord</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref>) and returns <emu-const>unused</emu-const>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Set <var>realmRecord</var>.<var class=\"field\">[[Intrinsics]]</var> to a new <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref>.</li><li>Set fields of <var>realmRecord</var>.<var class=\"field\">[[Intrinsics]]</var> with the values listed in <emu-xref href=\"#table-well-known-intrinsic-objects\"><a href=\"/ecmascript-data-types-and-values#table-well-known-intrinsic-objects\">Table 6</a></emu-xref>. The field names are the names listed in the “Intrinsic Name” column of the table. The value of each field is a new object value fully and recursively populated with property values as defined by the specification of each object in clauses <emu-xref href=\"#sec-global-object\"><a href=\"/global-object#sec-global-object\">19</a></emu-xref> through <emu-xref href=\"#sec-reflection\"><a href=\"/reflection#sec-reflection\">28</a></emu-xref>. All object property values are newly created object values. All values that are built-in <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function objects</a></emu-xref> are created by performing <emu-xref aoid=\"CreateBuiltinFunction\"><a href=\"/ordinary-and-exotic-objects-behaviours#sec-createbuiltinfunction\">CreateBuiltinFunction</a></emu-xref>(<var>steps</var>, <var>length</var>, <var>name</var>, <var>slots</var>, <var>realmRecord</var>, <var>proto</var>, <var>async</var>) where <var>steps</var> is the definition of that function provided by this specification, <var>name</var> is the initial value of the function's <emu-val>\"name\"</emu-val> property, <var>length</var> is the initial value of the function's <emu-val>\"length\"</emu-val> property, <var>slots</var> is a list of the names, if any, of the function's specified internal slots, <var>proto</var> is the specified value of the function's <var class=\"field\">[[Prototype]]</var> internal slot, and <var>async</var> is <emu-val>true</emu-val> if the function is described as “async” and <emu-val>false</emu-val> otherwise. The creation of the intrinsics and their properties must be ordered to avoid any dependencies upon objects that have not yet been created.</li><li>Perform <emu-xref aoid=\"AddRestrictedFunctionProperties\"><a href=\"/ordinary-and-exotic-objects-behaviours#sec-addrestrictedfunctionproperties\">AddRestrictedFunctionProperties</a></emu-xref>(<var>realmRecord</var>.<var class=\"field\">[[Intrinsics]]</var>.[[<emu-intrinsic>%Function.prototype%</emu-intrinsic>]], <var>realmRecord</var>).</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n    ","3.3":"<p>The abstract operation SetDefaultGlobalBindings takes argument <var>realmRecord</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref>) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> <emu-const>unused</emu-const> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>global</var> be <var>realmRecord</var>.<var class=\"field\">[[GlobalObject]]</var>.</li><li>For each property of the Global Object specified in clause <emu-xref href=\"#sec-global-object\"><a href=\"/global-object#sec-global-object\">19</a></emu-xref>, do<ol><li>Let <var>name</var> be the String value of the <emu-xref href=\"/ecmascript-data-types-and-values#property-name\"><a href=\"/ecmascript-data-types-and-values#property-name\">property name</a></emu-xref>.</li><li>Let <var>propertyDesc</var> be the fully populated data <emu-xref href=\"/ecmascript-data-types-and-values#sec-property-descriptor-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-property-descriptor-specification-type\">Property Descriptor</a></emu-xref> for the property, containing the specified attributes for the property. For properties listed in <emu-xref href=\"#sec-function-properties-of-the-global-object\"><a href=\"/global-object#sec-function-properties-of-the-global-object\">19.2</a></emu-xref>, <emu-xref href=\"#sec-constructor-properties-of-the-global-object\"><a href=\"/global-object#sec-constructor-properties-of-the-global-object\">19.3</a></emu-xref>, or <emu-xref href=\"#sec-other-properties-of-the-global-object\"><a href=\"/global-object#sec-other-properties-of-the-global-object\">19.4</a></emu-xref> the value of the <var class=\"field\">[[Value]]</var> attribute is the corresponding intrinsic object from <var>realmRecord</var>.</li><li>Perform ? <emu-xref aoid=\"DefinePropertyOrThrow\"><a href=\"/abstract-operations#sec-definepropertyorthrow\">DefinePropertyOrThrow</a></emu-xref>(<var>global</var>, <var>name</var>, <var>propertyDesc</var>).</li></ol></li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n    ","4.1":"<p>The abstract operation GetActiveScriptOrModule takes no arguments and returns a <emu-xref href=\"/ecmascript-language-scripts-and-modules#script-record\"><a href=\"/ecmascript-language-scripts-and-modules#script-record\">Script Record</a></emu-xref>, a <emu-xref href=\"/ecmascript-language-scripts-and-modules#sec-abstract-module-records\"><a href=\"/ecmascript-language-scripts-and-modules#sec-abstract-module-records\">Module Record</a></emu-xref>, or <emu-val>null</emu-val>. It is used to determine the running script or module, based on the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>. It performs the following steps when called:</p>\n\n      <emu-alg><ol><li class=\"exit\">If the <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref> is empty, return <emu-val>null</emu-val>.</li><li>Let <var>executionContext</var> be the topmost <emu-xref href=\"/executable-code-and-execution-contexts#sec-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#sec-execution-contexts\">execution context</a></emu-xref> on the <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref> whose ScriptOrModule component is not <emu-val>null</emu-val>.</li><li class=\"exit\">If no such <emu-xref href=\"/executable-code-and-execution-contexts#sec-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#sec-execution-contexts\">execution context</a></emu-xref> exists, return <emu-val>null</emu-val>.</li><li class=\"exit\">Return <var>executionContext</var>'s ScriptOrModule.</li></ol></emu-alg>\n    ","4.2":"<p>The abstract operation ResolveBinding takes argument <var>name</var> (a String) and optional argument <var>envRecord</var> (an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> or <emu-val>undefined</emu-val>) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> a <emu-xref href=\"/ecmascript-data-types-and-values#sec-reference-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-reference-record-specification-type\">Reference Record</a></emu-xref> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It is used to determine the binding of <var>name</var>. <var>envRecord</var> can be used to explicitly provide the <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> that is to be searched for the binding. It performs the following steps when called:</p>\n      <emu-alg><ol><li>If <var>envRecord</var> is not present or <var>envRecord</var> is <emu-val>undefined</emu-val>, then<ol><li>Set <var>envRecord</var> to the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>'s LexicalEnvironment.</li></ol></li><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>envRecord</var> is an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>.</li><li>Let <var>strict</var> be <emu-xref aoid=\"IsStrict\"><a href=\"/ecmascript-language-source-code#sec-isstrict\">IsStrict</a></emu-xref>(the syntactic production that is being evaluated).</li><li class=\"exit\">Return ? <emu-xref aoid=\"GetIdentifierReference\"><a href=\"/executable-code-and-execution-contexts#sec-getidentifierreference\">GetIdentifierReference</a></emu-xref>(<var>envRecord</var>, <var>name</var>, <var>strict</var>).</li></ol></emu-alg>\n      <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n        <p>The result of ResolveBinding is always a <emu-xref href=\"/ecmascript-data-types-and-values#sec-reference-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-reference-record-specification-type\">Reference Record</a></emu-xref> whose <var class=\"field\">[[ReferencedName]]</var> field is <var>name</var>.</p>\n      </div></emu-note>\n    ","4.3":"<p>The abstract operation GetThisEnvironment takes no arguments and returns an <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref>. It finds the <emu-xref href=\"/executable-code-and-execution-contexts#sec-environment-records\"><a href=\"/executable-code-and-execution-contexts#sec-environment-records\">Environment Record</a></emu-xref> that currently supplies the binding of the <emu-xref href=\"/ecmascript-language-lexical-grammar#sec-keywords-and-reserved-words\"><a href=\"/ecmascript-language-lexical-grammar#sec-keywords-and-reserved-words\">keyword</a></emu-xref> <code>this</code>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>envRecord</var> be the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>'s LexicalEnvironment.</li><li id=\"step-getthisenvironment-loop\">Repeat,<ol><li>Let <var>exists</var> be <var>envRecord</var>.HasThisBinding().</li><li class=\"exit\">If <var>exists</var> is <emu-val>true</emu-val>, return <var>envRecord</var>.</li><li>Let <var>outer</var> be <var>envRecord</var>.<var class=\"field\">[[OuterEnv]]</var>.</li><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>outer</var> is not <emu-val>null</emu-val>.</li><li>Set <var>envRecord</var> to <var>outer</var>.</li></ol></li></ol></emu-alg>\n      <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n        <p>The loop in step <emu-xref href=\"#step-getthisenvironment-loop\"><a href=\"/executable-code-and-execution-contexts#step-getthisenvironment-loop\">2</a></emu-xref> will always terminate because the list of environments always ends with the global environment which has a <code>this</code> binding.</p>\n      </div></emu-note>\n    ","4.4":"<p>The abstract operation ResolveThisBinding takes no arguments and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>. It determines the binding of the <emu-xref href=\"/ecmascript-language-lexical-grammar#sec-keywords-and-reserved-words\"><a href=\"/ecmascript-language-lexical-grammar#sec-keywords-and-reserved-words\">keyword</a></emu-xref> <code>this</code> using the LexicalEnvironment of the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>envRecord</var> be <emu-xref aoid=\"GetThisEnvironment\"><a href=\"/executable-code-and-execution-contexts#sec-getthisenvironment\">GetThisEnvironment</a></emu-xref>().</li><li class=\"exit\">Return ? <var>envRecord</var>.GetThisBinding().</li></ol></emu-alg>\n    ","4.5":"<p>The abstract operation GetNewTarget takes no arguments and returns an Object or <emu-val>undefined</emu-val>. It determines the NewTarget value using the LexicalEnvironment of the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>envRecord</var> be <emu-xref aoid=\"GetThisEnvironment\"><a href=\"/executable-code-and-execution-contexts#sec-getthisenvironment\">GetThisEnvironment</a></emu-xref>().</li><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <var>envRecord</var> has a <var class=\"field\">[[NewTarget]]</var> field.</li><li class=\"exit\">Return <var>envRecord</var>.<var class=\"field\">[[NewTarget]]</var>.</li></ol></emu-alg>\n    ","4.6":"<p>The abstract operation GetGlobalObject takes no arguments and returns an Object. It returns the <emu-xref href=\"/global-object#sec-global-object\"><a href=\"/global-object#sec-global-object\">global object</a></emu-xref> used by the currently <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>currentRealm</var> be <emu-xref href=\"/executable-code-and-execution-contexts#current-realm\"><a href=\"/executable-code-and-execution-contexts#current-realm\">the current Realm Record</a></emu-xref>.</li><li class=\"exit\">Return <var>currentRealm</var>.<var class=\"field\">[[GlobalObject]]</var>.</li></ol></emu-alg>\n    ","4.7":"<p>The abstract operation RunSuspendedContext takes arguments <var>context</var> (an <emu-xref href=\"/executable-code-and-execution-contexts#sec-execution-contexts\"><a href=\"/executable-code-and-execution-contexts#sec-execution-contexts\">execution context</a></emu-xref>) and <var>completionRecord</var> (a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">Completion Record</a></emu-xref>) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> either an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref> or <emu-const>unused</emu-const>, or an <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">abrupt completion</a></emu-xref>. It resumes <var>context</var> (sending it <var>completionRecord</var> as the resumption value), and waits for the result. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>callerContext</var> be the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>.</li><li>Suspend <var>callerContext</var>.</li><li>Push <var>context</var> onto the <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref>; <var>context</var> is now the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref>.</li><li><emu-meta effects=\"user-code\">Resume the suspended evaluation of <var>context</var></emu-meta> using <var>completionRecord</var> as the result of the operation that suspended it. Let <var>result</var> be the <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">Completion Record</a></emu-xref> returned by the resumed computation.</li><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: When we reach this step, <var>context</var> has already been removed from the <emu-xref href=\"/executable-code-and-execution-contexts#execution-context-stack\"><a href=\"/executable-code-and-execution-contexts#execution-context-stack\">execution context stack</a></emu-xref> and <var>callerContext</var> is the <emu-xref href=\"/executable-code-and-execution-contexts#running-execution-context\"><a href=\"/executable-code-and-execution-contexts#running-execution-context\">running execution context</a></emu-xref> again.</li><li class=\"exit\">Return <emu-xref aoid=\"Completion\"><a href=\"/notational-conventions#sec-completion-ao\">Completion</a></emu-xref>(<var>result</var>).</li></ol></emu-alg>\n    ","5.1":"<p>A <dfn variants=\"JobCallback Records\">JobCallback Record</dfn> is a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref> value used to store a <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function object</a></emu-xref> and a <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> value. <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">Function objects</a></emu-xref> that are invoked via a <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref> enqueued by the <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">host</a></emu-xref> may have additional <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> context. To propagate the state, <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-abstract-closure\"><a href=\"/ecmascript-data-types-and-values#sec-abstract-closure\">Abstract Closures</a></emu-xref> should not capture and call <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function objects</a></emu-xref> directly. Instead, use <emu-xref aoid=\"HostMakeJobCallback\"><a href=\"/executable-code-and-execution-contexts#sec-hostmakejobcallback\">HostMakeJobCallback</a></emu-xref> and <emu-xref aoid=\"HostCallJobCallback\"><a href=\"/executable-code-and-execution-contexts#sec-hostcalljobcallback\">HostCallJobCallback</a></emu-xref>.</p>\n      <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n        <p>The WHATWG HTML specification (<a href=\"https://html.spec.whatwg.org/\">https://html.spec.whatwg.org/</a>), for example, uses the <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> value to propagate the incumbent settings object for Promise callbacks.</p>\n      </div></emu-note>\n      <p>JobCallback Records have the fields listed in <emu-xref href=\"#table-jobcallback-records\"><a href=\"/executable-code-and-execution-contexts#table-jobcallback-records\">Table 23</a></emu-xref>.</p>\n      <emu-table id=\"table-jobcallback-records\" caption=\"JobCallback Record Fields\" data-num=\"23\">\n        <table>\n          <thead>\n            <tr>\n              <th>\n                Field Name\n              </th>\n              <th>\n                Value\n              </th>\n              <th>\n                Meaning\n              </th>\n            </tr>\n          </thead>\n          <tr>\n            <td>\n              <var class=\"field\">[[Callback]]</var>\n            </td>\n            <td>\n              a <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function object</a></emu-xref>\n            </td>\n            <td>\n              The function to invoke when the <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref> is invoked.\n            </td>\n          </tr>\n          <tr>\n            <td>\n              <var class=\"field\">[[HostDefined]]</var>\n            </td>\n            <td>\n              anything (default value is <emu-const>empty</emu-const>)\n            </td>\n            <td>\n              Field reserved for use by <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">hosts</a></emu-xref>.\n            </td>\n          </tr>\n        </table>\n      </emu-table>\n    ","5.2":"<p>The <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> abstract operation HostMakeJobCallback takes argument <var>callback</var> (a <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function object</a></emu-xref>) and returns a <emu-xref href=\"/executable-code-and-execution-contexts#sec-jobcallback-records\"><a href=\"/executable-code-and-execution-contexts#sec-jobcallback-records\">JobCallback Record</a></emu-xref>. It performs the following steps when called:</p>\n      <p>An implementation of HostMakeJobCallback must conform to the following requirements:</p>\n      <ul>\n        <li>It must return a <emu-xref href=\"/executable-code-and-execution-contexts#sec-jobcallback-records\"><a href=\"/executable-code-and-execution-contexts#sec-jobcallback-records\">JobCallback Record</a></emu-xref> whose <var class=\"field\">[[Callback]]</var> field is <var>callback</var>.</li>\n      </ul>\n      <p>The default implementation of HostMakeJobCallback performs the following steps when called:</p>\n      <emu-alg><ol><li class=\"exit\">Return the <emu-xref href=\"/executable-code-and-execution-contexts#sec-jobcallback-records\"><a href=\"/executable-code-and-execution-contexts#sec-jobcallback-records\">JobCallback Record</a></emu-xref> { <var class=\"field\">[[Callback]]</var>: <var>callback</var>, <var class=\"field\">[[HostDefined]]</var>: <emu-const>empty</emu-const> }.</li></ol></emu-alg>\n      <p>ECMAScript <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">hosts</a></emu-xref> that are not web browsers must use the default implementation of HostMakeJobCallback.</p>\n      <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n        <p>This is called at the time that the callback is passed to the function that is responsible for its being eventually scheduled and run. For example, <code>promise.then(thenAction)</code> calls MakeJobCallback on <code>thenAction</code> at the time of invoking <code>Promise.prototype.then</code>, not at the time of scheduling the reaction <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref>.</p>\n      </div></emu-note>\n    ","5.3":"<p>The <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> abstract operation HostCallJobCallback takes arguments <var>jobCallback</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#sec-jobcallback-records\"><a href=\"/executable-code-and-execution-contexts#sec-jobcallback-records\">JobCallback Record</a></emu-xref>), <var>value</var> (an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref>), and <var>argList</var> (a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref> of <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language values</a></emu-xref>) and returns either a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">normal completion containing</a></emu-xref> an <emu-xref href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\"><a href=\"/ecmascript-data-types-and-values#sec-ecmascript-language-types\">ECMAScript language value</a></emu-xref> or a <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">throw completion</a></emu-xref>.</p>\n      <p>An implementation of HostCallJobCallback must conform to the following requirements:</p>\n      <ul>\n        <li>It must perform and return the result of <emu-xref aoid=\"Call\"><a href=\"/abstract-operations#sec-call\">Call</a></emu-xref>(<var>jobCallback</var>.<var class=\"field\">[[Callback]]</var>, <var>value</var>, <var>argList</var>).</li>\n      </ul>\n      <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n        <p>This requirement means that <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">hosts</a></emu-xref> cannot change the <var class=\"field\">[[Call]]</var> behaviour of <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function objects</a></emu-xref> defined in this specification.</p>\n      </div></emu-note>\n      <p>The default implementation of HostCallJobCallback performs the following steps when called:</p>\n      <p>It performs the following steps when called:</p>\n<emu-alg><ol><li><emu-xref href=\"/notational-conventions#assert\"><a href=\"/notational-conventions#assert\">Assert</a></emu-xref>: <emu-xref aoid=\"IsCallable\"><a href=\"/abstract-operations#sec-iscallable\">IsCallable</a></emu-xref>(<var>jobCallback</var>.<var class=\"field\">[[Callback]]</var>) is <emu-val>true</emu-val>.</li><li class=\"exit\">Return ? <emu-xref aoid=\"Call\"><a href=\"/abstract-operations#sec-call\">Call</a></emu-xref>(<var>jobCallback</var>.<var class=\"field\">[[Callback]]</var>, <var>value</var>, <var>argList</var>).</li></ol></emu-alg>\n      <p>ECMAScript <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">hosts</a></emu-xref> that are not web browsers must use the default implementation of HostCallJobCallback.</p>\n    ","5.4":"<p>The <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> abstract operation HostEnqueueGenericJob takes arguments <var>job</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-abstract-closure\"><a href=\"/ecmascript-data-types-and-values#sec-abstract-closure\">Abstract Closure</a></emu-xref>) and <var>realm</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref>) and returns <emu-const>unused</emu-const>. It schedules <var>job</var> in the <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref> <var>realm</var> in the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> signified by <var>realm</var>.<var class=\"field\">[[AgentSignifier]]</var> to be performed at some future time. The <emu-xref href=\"/ecmascript-data-types-and-values#sec-abstract-closure\"><a href=\"/ecmascript-data-types-and-values#sec-abstract-closure\">Abstract Closures</a></emu-xref> used with this algorithm are intended to be scheduled without additional constraints, such as priority and ordering.</p>\n      <p>An implementation of HostEnqueueGenericJob must conform to the requirements in <emu-xref href=\"#sec-jobs\"><a href=\"/executable-code-and-execution-contexts#sec-jobs\">9.5</a></emu-xref>.</p>\n    ","5.5":"<p>The <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> abstract operation HostEnqueuePromiseJob takes arguments <var>job</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-abstract-closure\"><a href=\"/ecmascript-data-types-and-values#sec-abstract-closure\">Abstract Closure</a></emu-xref>) and <var>realm</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref> or <emu-val>null</emu-val>) and returns <emu-const>unused</emu-const>. It schedules <var>job</var> to be performed at some future time. The <emu-xref href=\"/ecmascript-data-types-and-values#sec-abstract-closure\"><a href=\"/ecmascript-data-types-and-values#sec-abstract-closure\">Abstract Closures</a></emu-xref> used with this algorithm are intended to be related to the handling of Promises, or otherwise, to be scheduled with equal priority to Promise handling operations.</p>\n\n      <p>An implementation of HostEnqueuePromiseJob must conform to the requirements in <emu-xref href=\"#sec-jobs\"><a href=\"/executable-code-and-execution-contexts#sec-jobs\">9.5</a></emu-xref> as well as the following:</p>\n      <ul>\n        <li>If <var>realm</var> is not <emu-val>null</emu-val>, each time <var>job</var> is invoked the implementation must perform <emu-xref href=\"/overview#implementation-defined\"><a href=\"/overview#implementation-defined\">implementation-defined</a></emu-xref> steps such that execution is <emu-xref href=\"/executable-code-and-execution-contexts#job-preparedtoevaluatecode\"><a href=\"/executable-code-and-execution-contexts#job-preparedtoevaluatecode\">prepared to evaluate ECMAScript code</a></emu-xref> at the time of <var>job</var>'s invocation.</li>\n        <li>Let <var>scriptOrModule</var> be <emu-xref aoid=\"GetActiveScriptOrModule\"><a href=\"/executable-code-and-execution-contexts#sec-getactivescriptormodule\">GetActiveScriptOrModule</a></emu-xref>() at the time HostEnqueuePromiseJob is invoked. If <var>realm</var> is not <emu-val>null</emu-val>, each time <var>job</var> is invoked the implementation must perform <emu-xref href=\"/overview#implementation-defined\"><a href=\"/overview#implementation-defined\">implementation-defined</a></emu-xref> steps such that <var>scriptOrModule</var> is the <emu-xref href=\"/executable-code-and-execution-contexts#job-activescriptormodule\"><a href=\"/executable-code-and-execution-contexts#job-activescriptormodule\">active script or module</a></emu-xref> at the time of <var>job</var>'s invocation.</li>\n        <li><emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Jobs</a></emu-xref> must run in the same order as the HostEnqueuePromiseJob invocations that scheduled them.</li>\n      </ul>\n\n      <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n        <p>The <var>realm</var> for <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Jobs</a></emu-xref> returned by <emu-xref aoid=\"NewPromiseResolveThenableJob\"><a href=\"/control-abstraction-objects#sec-newpromiseresolvethenablejob\">NewPromiseResolveThenableJob</a></emu-xref> is usually the result of calling <emu-xref aoid=\"GetFunctionRealm\"><a href=\"/abstract-operations#sec-getfunctionrealm\">GetFunctionRealm</a></emu-xref> on the <var>then</var> <emu-xref href=\"/ecmascript-data-types-and-values#function-object\"><a href=\"/ecmascript-data-types-and-values#function-object\">function object</a></emu-xref>. The <var>realm</var> for <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Jobs</a></emu-xref> returned by <emu-xref aoid=\"NewPromiseReactionJob\"><a href=\"/control-abstraction-objects#sec-newpromisereactionjob\">NewPromiseReactionJob</a></emu-xref> is usually the result of calling <emu-xref aoid=\"GetFunctionRealm\"><a href=\"/abstract-operations#sec-getfunctionrealm\">GetFunctionRealm</a></emu-xref> on the handler if the handler is not <emu-val>undefined</emu-val>. If the handler is <emu-val>undefined</emu-val>, <var>realm</var> is <emu-val>null</emu-val>. For both kinds of <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Jobs</a></emu-xref>, when <emu-xref aoid=\"GetFunctionRealm\"><a href=\"/abstract-operations#sec-getfunctionrealm\">GetFunctionRealm</a></emu-xref> completes abnormally (i.e. called on a revoked Proxy), <var>realm</var> is <emu-xref href=\"/executable-code-and-execution-contexts#current-realm\"><a href=\"/executable-code-and-execution-contexts#current-realm\">the current Realm Record</a></emu-xref> at the time of the <emu-xref aoid=\"GetFunctionRealm\"><a href=\"/abstract-operations#sec-getfunctionrealm\">GetFunctionRealm</a></emu-xref> call. When the <var>realm</var> is <emu-val>null</emu-val>, no user ECMAScript code will be evaluated and no new ECMAScript objects (e.g. Error objects) will be created. The WHATWG HTML specification (<a href=\"https://html.spec.whatwg.org/\">https://html.spec.whatwg.org/</a>), for example, uses <var>realm</var> to check for the ability to run script and for the <a href=\"https://html.spec.whatwg.org/#entry\">entry</a> concept.</p>\n      </div></emu-note>\n    ","5.6":"<p>The <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> abstract operation HostEnqueueTimeoutJob takes arguments <var>timeoutJob</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-abstract-closure\"><a href=\"/ecmascript-data-types-and-values#sec-abstract-closure\">Abstract Closure</a></emu-xref>), <var>realm</var> (a <emu-xref href=\"/executable-code-and-execution-contexts#realm-record\"><a href=\"/executable-code-and-execution-contexts#realm-record\">Realm Record</a></emu-xref>), and <var>milliseconds</var> (a non-negative <emu-xref href=\"/ecmascript-data-types-and-values#finite\"><a href=\"/ecmascript-data-types-and-values#finite\">finite</a></emu-xref> Number) and returns <emu-const>unused</emu-const>. It schedules <var>timeoutJob</var> in the <emu-xref href=\"/executable-code-and-execution-contexts#realm\"><a href=\"/executable-code-and-execution-contexts#realm\">realm</a></emu-xref> <var>realm</var> in the <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> signified by <var>realm</var>.<var class=\"field\">[[AgentSignifier]]</var> to be performed after at least <var>milliseconds</var> milliseconds.</p>\n      <p>An implementation of HostEnqueueTimeoutJob must conform to the requirements in <emu-xref href=\"#sec-jobs\"><a href=\"/executable-code-and-execution-contexts#sec-jobs\">9.5</a></emu-xref>.</p>\n    ","6.1":"<p>The abstract operation AgentSignifier takes no arguments and returns an <emu-xref href=\"/executable-code-and-execution-contexts#sec-agents\"><a href=\"/executable-code-and-execution-contexts#sec-agents\">agent signifier</a></emu-xref>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>agentRecord</var> be the <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Record</a></emu-xref> of the <emu-xref href=\"/executable-code-and-execution-contexts#surrounding-agent\"><a href=\"/executable-code-and-execution-contexts#surrounding-agent\">surrounding agent</a></emu-xref>.</li><li class=\"exit\">Return <var>agentRecord</var>.<var class=\"field\">[[Signifier]]</var>.</li></ol></emu-alg>\n    ","6.2":"<p>The abstract operation AgentCanSuspend takes no arguments and returns a Boolean. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>agentRecord</var> be the <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Record</a></emu-xref> of the <emu-xref href=\"/executable-code-and-execution-contexts#surrounding-agent\"><a href=\"/executable-code-and-execution-contexts#surrounding-agent\">surrounding agent</a></emu-xref>.</li><li class=\"exit\">Return <var>agentRecord</var>.<var class=\"field\">[[CanBlock]]</var>.</li></ol></emu-alg>\n      <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n        <p>In some environments it may not be reasonable for a given <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref> to suspend. For example, in a web browser environment, it may be reasonable to disallow suspending a document's main event handling thread, while still allowing workers' event handling threads to suspend.</p>\n      </div></emu-note>\n    ","6.3":"<p>The abstract operation IncrementModuleAsyncEvaluationCount takes no arguments and returns a non-negative <emu-xref href=\"/notational-conventions#integer\"><a href=\"/notational-conventions#integer\">integer</a></emu-xref>. It performs the following steps when called:</p>\n      <emu-alg><ol><li>Let <var>agentRecord</var> be the <emu-xref href=\"/executable-code-and-execution-contexts#agent-record\"><a href=\"/executable-code-and-execution-contexts#agent-record\">Agent Record</a></emu-xref> of the <emu-xref href=\"/executable-code-and-execution-contexts#surrounding-agent\"><a href=\"/executable-code-and-execution-contexts#surrounding-agent\">surrounding agent</a></emu-xref>.</li><li>Let <var>count</var> be <var>agentRecord</var>.<var class=\"field\">[[ModuleAsyncEvaluationCount]]</var>.</li><li>Set <var>agentRecord</var>.<var class=\"field\">[[ModuleAsyncEvaluationCount]]</var> to <var>count</var> + 1.</li><li class=\"exit\">Return <var>count</var>.</li></ol></emu-alg>\n      <emu-note><span class=\"note\">Note</span><div class=\"note-contents\">\n        <p>This value is only used to keep track of the relative evaluation order between pending modules. An implementation may unobservably reset <var class=\"field\">[[ModuleAsyncEvaluationCount]]</var> to 0 whenever there are no pending modules.</p>\n      </div></emu-note>\n    ","9.1":"<p>This specification does not make any guarantees that any object or symbol will be garbage collected. Objects or symbols which are not <emu-xref href=\"/executable-code-and-execution-contexts#sec-liveness\"><a href=\"/executable-code-and-execution-contexts#sec-liveness\">live</a></emu-xref> may be released after long periods of time, or never at all. For this reason, this specification uses the term “may” when describing behaviour triggered by garbage collection.</p>\n\n      <p>The semantics of <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRefs</a></emu-xref> and <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistrys</a></emu-xref> is based on two operations which happen at particular points in time:</p>\n\n      <ul>\n        <li>\n          When <code>WeakRef.prototype.deref</code> is called, the referent (if <emu-val>undefined</emu-val> is not returned) is kept alive so that subsequent, synchronous accesses also return the same value. This list is reset when synchronous work is done using the <emu-xref aoid=\"ClearKeptObjects\"><a href=\"/executable-code-and-execution-contexts#sec-clear-kept-objects\">ClearKeptObjects</a></emu-xref> abstract operation.\n        </li>\n\n        <li>\n          When an object or symbol which is registered with a <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistry</a></emu-xref> becomes unreachable, a call of the <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistry</a></emu-xref>'s cleanup callback may eventually be made, after synchronous ECMAScript execution completes. The <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistry</a></emu-xref> cleanup is performed with the <emu-xref aoid=\"CleanupFinalizationRegistry\"><a href=\"/executable-code-and-execution-contexts#sec-cleanup-finalization-registry\">CleanupFinalizationRegistry</a></emu-xref> abstract operation.\n        </li>\n      </ul>\n\n      <p>Neither of these actions (<emu-xref aoid=\"ClearKeptObjects\"><a href=\"/executable-code-and-execution-contexts#sec-clear-kept-objects\">ClearKeptObjects</a></emu-xref> or <emu-xref aoid=\"CleanupFinalizationRegistry\"><a href=\"/executable-code-and-execution-contexts#sec-cleanup-finalization-registry\">CleanupFinalizationRegistry</a></emu-xref>) may interrupt synchronous ECMAScript execution. Because <emu-xref href=\"/overview#host\"><a href=\"/overview#host\">hosts</a></emu-xref> may assemble longer, synchronous ECMAScript execution runs, this specification defers the scheduling of <emu-xref aoid=\"ClearKeptObjects\"><a href=\"/executable-code-and-execution-contexts#sec-clear-kept-objects\">ClearKeptObjects</a></emu-xref> and <emu-xref aoid=\"CleanupFinalizationRegistry\"><a href=\"/executable-code-and-execution-contexts#sec-cleanup-finalization-registry\">CleanupFinalizationRegistry</a></emu-xref> to the <emu-xref href=\"/overview#host-environment\"><a href=\"/overview#host-environment\">host environment</a></emu-xref>.</p>\n\n      <p>Some ECMAScript implementations include garbage collector implementations which run in the background, including when ECMAScript is idle. Letting the <emu-xref href=\"/overview#host-environment\"><a href=\"/overview#host-environment\">host environment</a></emu-xref> schedule <emu-xref aoid=\"CleanupFinalizationRegistry\"><a href=\"/executable-code-and-execution-contexts#sec-cleanup-finalization-registry\">CleanupFinalizationRegistry</a></emu-xref> allows it to resume ECMAScript execution in order to run finalizer work, which may free up held values, reducing overall memory usage.</p>\n    ","9.2":"<p>For some set of objects and/or symbols <var>objSet</var> a <dfn>hypothetical WeakRef-oblivious</dfn> execution with respect to <var>objSet</var> is an execution whereby the abstract operation <emu-xref aoid=\"WeakRefDeref\"><a href=\"/managing-memory#sec-weakrefderef\">WeakRefDeref</a></emu-xref> of a <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref> whose referent is an element of <var>objSet</var> always returns <emu-val>undefined</emu-val>.</p>\n\n      <emu-note data-num=\"1\"><span class=\"note\">Note 1</span><div class=\"note-contents\">\n        <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref>-obliviousness, together with liveness, capture two notions. One, that a <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref> itself does not keep its referent alive. Two, that cycles in liveness does not imply that a value is live. To be concrete, if determining <var>v</var>'s liveness depends on determining the liveness of a <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref> referent, <var>r</var>, <var>r</var>'s liveness cannot assume <var>v</var>'s liveness, which would be circular reasoning.\n      </div></emu-note>\n      <emu-note data-num=\"2\"><span class=\"note\">Note 2</span><div class=\"note-contents\">\n        <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref>-obliviousness is defined on sets of objects or symbols instead of individual values to account for cycles. If it were defined on individual values, then a <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref> referent in a cycle will be considered live even though its identity is only observed via other <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref> referents in the cycle.\n      </div></emu-note>\n      <emu-note data-num=\"3\"><span class=\"note\">Note 3</span><div class=\"note-contents\">\n        Colloquially, we say that an individual object or symbol is live if every set containing it is live.\n      </div></emu-note>\n\n      <p>At any point during evaluation, a set of objects and/or symbols <var>objSet</var> is considered <dfn>live</dfn> if either of the following conditions is met:</p>\n\n      <ul>\n        <li>\n          Any element in <var>objSet</var> is included in any <emu-xref href=\"/executable-code-and-execution-contexts#agent\"><a href=\"/executable-code-and-execution-contexts#agent\">agent</a></emu-xref>'s <var class=\"field\">[[KeptAlive]]</var> <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">List</a></emu-xref>.\n        </li>\n        <li>\n          There exists a valid future hypothetical WeakRef-oblivious execution with respect to <var>objSet</var> that observes the identity of any value in <var>objSet</var>.\n        </li>\n      </ul>\n      <emu-note data-num=\"4\"><span class=\"note\">Note 4</span><div class=\"note-contents\">\n        The second condition above intends to capture the intuition that a value is live if its identity is observable via non-<emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref> means. A value's identity may be observed by observing a strict equality comparison or observing the value being used as key in a Map.\n      </div></emu-note>\n      <emu-note data-num=\"5\"><span class=\"note\">Note 5</span><div class=\"note-contents\">\n        <p>Presence of an object or a symbol in a field, an internal slot, or a property does not imply that the value is live. For example if the value in question is never passed back to the program, then it cannot be observed.</p>\n\n        <p>This is the case for keys in a WeakMap, members of a WeakSet, as well as the <var class=\"field\">[[WeakRefTarget]]</var> and <var class=\"field\">[[UnregisterToken]]</var> fields of a <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistry</a></emu-xref> Cell record.</p>\n\n        <p>The above definition implies that, if a key in a WeakMap is not live, then its corresponding value is not necessarily live either.</p>\n      </div></emu-note>\n      <emu-note data-num=\"6\"><span class=\"note\">Note 6</span><div class=\"note-contents\">\n        Liveness is the lower bound for guaranteeing which <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRefs</a></emu-xref> engines must not empty. Liveness as defined here is undecidable. In practice, engines use conservative approximations such as reachability. There is expected to be significant implementation leeway.\n      </div></emu-note>\n    ","9.3":"<p>At any time, if a set of objects and/or symbols <var>objSet</var> is not <emu-xref href=\"/executable-code-and-execution-contexts#sec-liveness\"><a href=\"/executable-code-and-execution-contexts#sec-liveness\">live</a></emu-xref>, an ECMAScript implementation may perform the following steps atomically:</p>\n\n      <emu-alg><ol><li>For each element <var>value</var> of <var>objSet</var>, do<ol><li>For each <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref> <var>ref</var> such that <var>ref</var>.<var class=\"field\">[[WeakRefTarget]]</var> is <var>value</var>, do<ol><li>Set <var>ref</var>.<var class=\"field\">[[WeakRefTarget]]</var> to <emu-const>empty</emu-const>.</li></ol></li><li>For each <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistry</a></emu-xref> <var>fg</var> such that <var>fg</var>.<var class=\"field\">[[Cells]]</var> contains a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref> <var>cell</var> such that <var>cell</var>.<var class=\"field\">[[WeakRefTarget]]</var> is <var>value</var>, do<ol><li>Set <var>cell</var>.<var class=\"field\">[[WeakRefTarget]]</var> to <emu-const>empty</emu-const>.</li><li>Let <var>enqueueCleanup</var> be an <emu-xref href=\"/overview#implementation-defined\"><a href=\"/overview#implementation-defined\">implementation-defined</a></emu-xref> choice of either <emu-val>true</emu-val> or <emu-val>false</emu-val>.</li><li>If <var>enqueueCleanup</var> is <emu-val>true</emu-val>, perform <emu-xref aoid=\"HostEnqueueFinalizationRegistryCleanupJob\"><a href=\"/executable-code-and-execution-contexts#sec-host-cleanup-finalization-registry\">HostEnqueueFinalizationRegistryCleanupJob</a></emu-xref>(<var>fg</var>).</li></ol></li><li>For each WeakMap <var>map</var> such that <var>map</var>.<var class=\"field\">[[WeakMapData]]</var> contains a <emu-xref href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-list-and-record-specification-type\">Record</a></emu-xref> <var>entry</var> such that <var>entry</var>.<var class=\"field\">[[Key]]</var> is <var>value</var>, do<ol><li>Set <var>entry</var>.<var class=\"field\">[[Key]]</var> to <emu-const>empty</emu-const>.</li><li>Set <var>entry</var>.<var class=\"field\">[[Value]]</var> to <emu-const>empty</emu-const>.</li></ol></li><li>For each WeakSet <var>set</var> such that <var>set</var>.<var class=\"field\">[[WeakSetData]]</var> contains <var>value</var>, do<ol><li>Replace the element of <var>set</var>.<var class=\"field\">[[WeakSetData]]</var> whose value is <var>value</var> with an element whose value is <emu-const>empty</emu-const>.</li></ol></li></ol></li></ol></emu-alg>\n\n      <emu-note data-num=\"1\"><span class=\"note\">Note 1</span><div class=\"note-contents\">\n        <p>Together with the definition of liveness, this clause prescribes optimizations that an implementation may apply regarding <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRefs</a></emu-xref>.</p>\n\n        <p>It is possible to access an object without observing its identity. Optimizations such as dead variable elimination and scalar replacement on properties of non-escaping objects whose identity is not observed are allowed. These optimizations are thus allowed to observably empty <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRefs</a></emu-xref> that point to such objects.</p>\n\n        <p>On the other hand, if an object's identity is observable, and that object is in the <var class=\"field\">[[WeakRefTarget]]</var> internal slot of a <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref>, optimizations such as rematerialization that observably empty the <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref> are prohibited.</p>\n\n        <p>Because calling <emu-xref aoid=\"HostEnqueueFinalizationRegistryCleanupJob\"><a href=\"/executable-code-and-execution-contexts#sec-host-cleanup-finalization-registry\">HostEnqueueFinalizationRegistryCleanupJob</a></emu-xref> is optional, registered objects in a <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistry</a></emu-xref> do not necessarily hold that <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistry</a></emu-xref> <emu-xref href=\"/executable-code-and-execution-contexts#sec-liveness\"><a href=\"/executable-code-and-execution-contexts#sec-liveness\">live</a></emu-xref>. Implementations may omit <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistry</a></emu-xref> callbacks for any reason, e.g., if the <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistry</a></emu-xref> itself becomes dead, or if the application is shutting down.</p>\n      </div></emu-note>\n      <emu-note data-num=\"2\"><span class=\"note\">Note 2</span><div class=\"note-contents\">\n        <p>Implementations are not obligated to empty <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRefs</a></emu-xref> for maximal sets of non-<emu-xref href=\"/executable-code-and-execution-contexts#sec-liveness\"><a href=\"/executable-code-and-execution-contexts#sec-liveness\">live</a></emu-xref> objects or symbols.</p>\n        <p>If an implementation chooses a non-<emu-xref href=\"/executable-code-and-execution-contexts#sec-liveness\"><a href=\"/executable-code-and-execution-contexts#sec-liveness\">live</a></emu-xref> set <var>objSet</var> in which to empty <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRefs</a></emu-xref>, this definition requires that it empties <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRefs</a></emu-xref> for all values in <var>objSet</var> simultaneously. In other words, it is not conformant for an implementation to empty a <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRef</a></emu-xref> pointing to a value <var>v</var> without emptying out other <emu-xref href=\"/managing-memory#sec-weak-ref-constructor\"><a href=\"/managing-memory#sec-weak-ref-constructor\">WeakRefs</a></emu-xref> that, if not emptied, could result in an execution that observes the value of <var>v</var>.</p>\n      </div></emu-note>\n    ","9.4":"","9.4.1":"<p>The <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> abstract operation HostEnqueueFinalizationRegistryCleanupJob takes argument <var>finalizationRegistry</var> (a <emu-xref href=\"/managing-memory#sec-finalization-registry-constructor\"><a href=\"/managing-memory#sec-finalization-registry-constructor\">FinalizationRegistry</a></emu-xref>) and returns <emu-const>unused</emu-const>. It performs the following steps when called:</p>\n        <p>Let <var>cleanupJob</var> be a new <emu-xref href=\"/executable-code-and-execution-contexts#job\"><a href=\"/executable-code-and-execution-contexts#job\">Job</a></emu-xref> <emu-xref href=\"/ecmascript-data-types-and-values#sec-abstract-closure\"><a href=\"/ecmascript-data-types-and-values#sec-abstract-closure\">Abstract Closure</a></emu-xref> with no parameters that captures <var>finalizationRegistry</var> and performs the following steps when called:</p>\n        <emu-alg><ol><li>Let <var>cleanupResult</var> be <emu-xref aoid=\"Completion\"><a href=\"/notational-conventions#sec-completion-ao\">Completion</a></emu-xref>(<emu-xref aoid=\"CleanupFinalizationRegistry\"><a href=\"/executable-code-and-execution-contexts#sec-cleanup-finalization-registry\">CleanupFinalizationRegistry</a></emu-xref>(<var>finalizationRegistry</var>)).</li><li>If <var>cleanupResult</var> is an <emu-xref href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\"><a href=\"/ecmascript-data-types-and-values#sec-completion-record-specification-type\">abrupt completion</a></emu-xref>, perform any <emu-xref href=\"/overview#host-defined\"><a href=\"/overview#host-defined\">host-defined</a></emu-xref> steps for reporting the error.</li><li class=\"exit\">Return <emu-const>unused</emu-const>.</li></ol></emu-alg>\n        <p>An implementation of HostEnqueueFinalizationRegistryCleanupJob schedules <var>cleanupJob</var> to be performed at some future time, if possible. It must also conform to the requirements in <emu-xref href=\"#sec-jobs\"><a href=\"/executable-code-and-execution-contexts#sec-jobs\">9.5</a></emu-xref>.</p>\n      "};
export function Sec({ id }) {
  const html = sections[id] ?? '';
  return <div dangerouslySetInnerHTML={{ __html: html }} />;
}
